package com.iviystical.collectionlogshowcase;

import com.iviystical.collectionlogshowcase.cox.CoxChatCensorMode;
import com.iviystical.collectionlogshowcase.overlay.PanelStyle;
import com.iviystical.collectionlogshowcase.overlay.RightPanelStat;
import com.iviystical.collectionlogshowcase.sound.CollectionVoice;
import com.iviystical.collectionlogshowcase.rarity.PreviewTier;
import com.iviystical.collectionlogshowcase.rarity.RarityBasis;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("collection-log-showcase")
public interface CollectionLogShowcaseConfig extends Config
{
	@ConfigSection(
		name = "Preview",
		description = "Preview the popup without waiting for an unlock",
		position = 0
	)
	String previewSection = "previewSection";

	@ConfigSection(
		name = "Popup",
		description = "Our animated popup or native popup with audio",
		position = 1
	)
	String styleSection = "styleSection";

	@ConfigSection(
		name = "Rarity",
		description = "How an item's rarity tier is determined",
		position = 6
	)
	String raritySection = "raritySection";

	@ConfigSection(
		name = "Statistics",
		description = "Choose the additional statistic and primary statistic ordering",
		position = 7
	)
	String overlaySection = "overlaySection";

	@ConfigSection(
		name = "Audio",
		description = "Sound effects played on new collection log unlocks",
		position = 2
	)
	String audioSection = "audioSection";

	@ConfigSection(
		name = "Appearance",
		description = "Tune to your liking",
		position = 4
	)
	String appearanceSection = "appearanceSection";

	@ConfigSection(
		name = "Text colours",
		description = "Colour of the caption and statistic text",
		position = 5
	)
	String textColoursSection = "textColoursSection";

	@ConfigSection(
		name = "Chambers of Xeric censor",
		description = "Hiding CoX purples until chest opened.",
		position = 8
	)
	String tweaksSection = "tweaksSection";

	@ConfigItem(
		keyName = "previewTier",
		name = "Preview popup",
		description = "Shows a random item popup of the selected tier",
		position = 0,
		section = previewSection
	)
	default PreviewTier previewTier()
	{
		return PreviewTier.NONE;
	}

	@ConfigItem(keyName = "previewLoop", name = "Loop", description = "Repeat the selected preview after it closes", position = 1, section = previewSection)
	default boolean previewLoop() { return false; }

	@ConfigItem(keyName = "delayCollectionScreenshot", name = "Delay collection screenshot", description = "Wait 1.5 seconds after the drawer opens before taking popup-based collection screenshots. Requires Screenshot plugin; chat-only screenshots use native timing.", position = 10, section = appearanceSection)
	default boolean delayCollectionScreenshot() { return true; }

	@ConfigItem(
		keyName = "rarityBasis",
		name = "Rarity based on",
		description = "What the rarity tiers are based on",
		position = 0,
		section = raritySection
	)
	default RarityBasis rarityBasis()
	{
		return RarityBasis.COMBINATION;
	}

	@ConfigItem(
		keyName = "valueUncommonThreshold",
		name = "Uncommon at (gp)",
		description = "Value threshold for uncommon tier",
		position = 1,
		section = raritySection
	)
	default int valueUncommonThreshold()
	{
		return 100_000;
	}

	@ConfigItem(
		keyName = "valueRareThreshold",
		name = "Rare at (gp)",
		description = "Value threshold for rare tier",
		position = 2,
		section = raritySection
	)
	default int valueRareThreshold()
	{
		return 1_000_000;
	}

	@ConfigItem(
		keyName = "valueVeryRareThreshold",
		name = "Very rare at (gp)",
		description = "Value threshold for very rare tier",
		position = 3,
		section = raritySection
	)
	default int valueVeryRareThreshold()
	{
		return 10_000_000;
	}

	@ConfigItem(
		keyName = "showKillCount",
		name = "Show kill/activity count",
		description = "Show the matching kill or activity count from game chat when available. Previews show simulated counts for layout testing.",
		position = 0,
		section = overlaySection
	)
	default boolean showKillCount()
	{
		return false;
	}

	@ConfigItem(
		keyName = "rightPanelStat",
		name = "Primary statistic",
		description = "Choose whether value or drop rate is listed first",
		position = 1,
		section = overlaySection
	)
	default RightPanelStat rightPanelStat()
	{
		return RightPanelStat.DROP_RATE;
	}

	@ConfigItem(
		keyName = "bulkUnlockSfx",
		name = "Bulk unlock SFX",
		description = "When multiple items unlock at once, play a single sound instead",
		position = 0,
		section = audioSection
	)
	default boolean bulkUnlockSfx()
	{
		return false;
	}

	@ConfigItem(keyName = "soundEnabled", name = "Play collection log audio", description = "Play the selected voice for every collection log slot, including pets", position = 1, section = audioSection)
	default boolean soundEnabled() { return true; }

	@Range(min = 0, max = 100)
	@ConfigItem(keyName = "soundVolume", name = "Volume", description = "Volume for all collection log sounds", position = 2, section = audioSection)
	default int soundVolume() { return 65; }

	@ConfigSection(name = "Audio files", description = "Choose a collection log voice or your own WAV", position = 3)
	String audioFilesSection = "audioFilesSection";

	@ConfigItem(keyName = "collectionVoice", name = "Voice", description = "Choose a voice, or Random to pick a bundled clip for each unlock without consecutive repeats", position = 0, section = audioFilesSection)
	default CollectionVoice collectionVoice() { return CollectionVoice.C_ENGINEER; }

	@ConfigItem(keyName = "customSoundFile", name = "Custom WAV filename", description = "For Custom voice: filename inside .runelite/plugin-data/collection-log-showcase/sounds/", position = 1, section = audioFilesSection)
	default String customSoundFile() { return "custom.wav"; }

	@ConfigItem(
		keyName = "showProgressBar",
		name = "Show progress bar",
		description = "Show your collection log progress in the center bar",
		position = 0,
		section = appearanceSection
	)
	default boolean showProgressBar()
	{
		return true;
	}

	@ConfigItem(
		keyName = "compactShowOwnership",
		name = "Show ownership",
		description = "Include the percentage of players who own the item in the stat line",
		position = 10,
		section = appearanceSection
	)
	default boolean compactShowOwnership()
	{
		return false;
	}

	@ConfigItem(
		keyName = "compactShimmer",
		name = "Glass shimmer",
		description = "Sweep a soft glass highlight across the banner once during its reveal",
		position = 12,
		section = appearanceSection
	)
	default boolean compactShimmer()
	{
		return true;
	}

	@ConfigItem(keyName = "showGlow", name = "Show glow", description = "Soft rarity-coloured glow around the drawer border", position = 12, section = appearanceSection)
	default boolean showGlow() { return false; }

	@ConfigItem(
		keyName = "compactTextColour",
		name = "Item and values",
		description = "High contrast text colour for the compact reward banner",
		position = 11,
		section = textColoursSection
	)
	default Color compactTextColour()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "overlayDisplaySeconds",
		name = "Overlay display duration (seconds)",
		description = "How long each new collection log item stays on screen",
		position = 1,
		section = appearanceSection
	)
	default int overlayDisplaySeconds()
	{
		return 6;
	}

	@Range(min = 200, max = 1500)
	@ConfigItem(keyName = "fadeOutMillis", name = "Drawer close duration (ms)",
		description = "Length of the reverse drawer close animation, including previews", position = 3, section = appearanceSection)
	default int fadeOutMillis() { return 600; }

	@Range(min = 50, max = 200)
	@ConfigItem(
		keyName = "overlayScalePercent",
		name = "Popup scale (%)",
		description = "Size of the popup",
		position = 2,
		section = appearanceSection
	)
	default int overlayScalePercent()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "backgroundOpacity",
		name = "Background opacity (%)",
		description = "Background opacity",
		position = 4,
		section = appearanceSection
	)
	default int backgroundOpacity()
	{
		return 100;
	}

	// Floored above 0 so the popup can never be made entirely invisible.
	@Range(min = 10, max = 100)
	@ConfigItem(
		keyName = "foregroundOpacity",
		name = "Border & text opacity (%)",
		description = "Foreground opacity",
		position = 5,
		section = appearanceSection
	)
	default int foregroundOpacity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "panelStyle",
		name = "Mode",
		description = "Showcase: animated replacement. Native: standard game popup. Both use your selected audio settings.",
		position = 0,
		section = styleSection
	)
	default PanelStyle panelStyle()
	{
		return PanelStyle.COMPACT;
	}

	@ConfigItem(
		keyName = "colourCaption",
		name = "Caption text",
		description = "Colour of the Collection Log caption at the top",
		position = 0,
		section = textColoursSection
	)
	default Color colourCaption()
	{
		return new Color(0xFF981F);
	}

	@ConfigItem(
		keyName = "delayCoxPopupUntilChest",
		name = "Delay CoX popups until chest",
		description = "Hide the collection log popup for CoX purples until the reward chest, storage or bank is opened. The collection log screenshot is taken then too.",
		position = 0,
		section = tweaksSection
	)
	default boolean delayCoxPopupUntilChest()
	{
		return false;
	}

	@ConfigItem(
		keyName = "coxChatCensor",
		name = "Chatbox censor",
		description = "Replace CoX purples in chat with ??? until the reward chest, storage or bank is opened",
		position = 1,
		section = tweaksSection
	)
	default CoxChatCensorMode coxChatCensor()
	{
		return CoxChatCensorMode.OFF;
	}

}

package com.iviystical.collectionlogshowcase;

import com.google.inject.Provides;
import com.iviystical.collectionlogshowcase.cox.CoxChatCensor;
import com.iviystical.collectionlogshowcase.cox.CoxChatCensorMode;
import com.iviystical.collectionlogshowcase.cox.CoxLootParser;
import com.iviystical.collectionlogshowcase.cox.CoxScreenshot;
import com.iviystical.collectionlogshowcase.droprate.DropRateResolver;
import com.iviystical.collectionlogshowcase.droprate.LocalDropRateDatasetLoader;
import com.iviystical.collectionlogshowcase.killcount.KillCountKind;
import com.iviystical.collectionlogshowcase.killcount.KillCountTracker;
import com.iviystical.collectionlogshowcase.overlay.CollectionLogOverlay;
import com.iviystical.collectionlogshowcase.overlay.PanelStyle;
import com.iviystical.collectionlogshowcase.rarity.ItemIdResolver;
import com.iviystical.collectionlogshowcase.rarity.LocalRarityDatasetLoader;
import com.iviystical.collectionlogshowcase.rarity.PreviewTier;
import com.iviystical.collectionlogshowcase.rarity.RarityResolver;
import com.iviystical.collectionlogshowcase.rarity.RarityResult;
import java.util.Comparator;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Singleton;
import net.runelite.client.audio.AudioPlayer;
import com.iviystical.collectionlogshowcase.sound.SoundManager;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Collection Log Showcase",
	internalName = "collection-log-showcase",
	legacyDataDirectory = "collection-log-showcase",
	description = "A standalone fork of Collection Log Popup Enhanced with animated popups and creator voices",
	conflicts = {"Collection Log Popup Enhanced"}
)
public class CollectionLogShowcasePlugin extends Plugin
{
	private static final Pattern NEW_COLLECTION_LOG_ITEM = Pattern.compile("New item added to your collection log: (.*)");

	// Dev-only: "::clogtest [count]" shows random items from the rarity dataset; "::clogtest <item
	// name>" runs a specific name through the real detection pipeline, kill count correlation
	// included. Only usable in --developer-mode (the gradle "run" task), not on a hub-installed build.
	private static final String TEST_COMMAND = "clogtest";
	// Dev-only, for testing the CoX delay without a raid: "::coxsim <item> [player]" posts the chat
	// lines a raid end produces, "::coxopen" does what opening the chest does. See TESTING-COX.md.
	private static final String COX_SIMULATE_COMMAND = "coxsim";
	private static final String COX_OPEN_COMMAND = "coxopen";
	private static final String CONFIG_GROUP = "collection-log-showcase";

	// Matched against VarClientID.NOTIFICATION_TITLE to tell our notification apart from the combat
	// task and league task ones that share the same widget. Same string ScreenshotPlugin matches on.
	private static final String COLLECTION_LOG_NOTIFICATION_TITLE = "Collection log";

	// Swapped in for the notification title while a held CoX popup is on screen, so the Screenshot
	// plugin - which matches the title to "Collection log" - skips it. See onScriptPreFired.
	private static final String SPOOFED_NOTIFICATION_TITLE = " ";

	// VarbitID.OPTION_COLLECTION_NEW_ITEM value for "chat message only" - the Screenshot plugin then
	// screenshots from the chat line instead of the popup, which happens at raid end regardless.
	private static final int COLLECTION_NEW_ITEM_CHAT_ONLY = 1;

	private static final String COX_CENSOR_PLUGIN_CLASS = "com.coxspecialloothider.CoxSpecialLootHiderPlugin";
	private static final String COX_CENSOR_CONFLICT_WARNING = "<col=ff0000>Collection Log Showcase: please turn off"
		+ " the CoX Censor plugin, this plugin already does the same thing.";
	private static final String COX_CHAT_CENSOR_HINT = " To hide CoX loot in chat as well, turn on 'Chatbox censor'"
		+ " under 'Chambers of Xeric censor' in this plugin's settings.";

	// Opening any of these reveals the raid's loot, so a held popup is no longer a spoiler. Private
	// storage and the bank cover leaving the raid without looting the chest.
	private static final int[] COX_LOOT_REVEAL_INTERFACES = {
		InterfaceID.RAIDS_REWARDS,
		InterfaceID.RAIDS_STORAGE_PRIVATE,
		InterfaceID.BANKMAIN,
	};

	// The notification's painted widgets. UNIVERSE, CONTAINER and CONTENT are excluded on purpose -
	// the open animation resizes those, and hiding one stalls it before the screenshot fires.
	private static final int[] NATIVE_POPUP_PAINT_COMPONENTS = {
		InterfaceID.NotificationDisplay.BACKGROUND,
		InterfaceID.NotificationDisplay.FRAME,
		InterfaceID.NotificationDisplay.TITLE,
		InterfaceID.NotificationDisplay.TITLE_TEXT,
		InterfaceID.NotificationDisplay.MAIN,
		InterfaceID.NotificationDisplay.MAIN_TEXT,
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private RarityResolver rarityResolver;

	@Inject
	private ItemIdResolver itemIdResolver;

	@Inject
	private KillCountTracker killCountTracker;

	@Inject
	private DropRateResolver dropRateResolver;

	@Inject
	private LocalDropRateDatasetLoader localDropRateDatasetLoader;

	@Inject
	private LocalRarityDatasetLoader localRarityDatasetLoader;

	@Inject
	private EventBus eventBus;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CollectionLogOverlay collectionLogOverlay;

	@Inject
	private CollectionLogShowcaseConfig config;

	@Inject
	private CoxChatCensor coxChatCensor;

	@Inject
	private CoxScreenshot coxScreenshot;

	@Inject
	private PluginManager pluginManager;

	private PreviewTier previousPreviewTier = PreviewTier.NONE;

	@Inject
	private ConfigManager configManager;

	// The real notification title while it is swapped for SPOOFED_NOTIFICATION_TITLE, else null.
	private String spoofedNotificationTitle;

	private boolean coxCensorConflictWarned;

	// Tracked rather than read from the event, which has no previous value - so the warning fires on entry only.
	private boolean inCoxRaid;

	@Override
	protected void startUp() throws Exception
	{
		SettingsMigration.initializePreview(configManager);
		previousPreviewTier = PreviewTier.NONE;
		eventBus.register(itemIdResolver);
		eventBus.register(killCountTracker);
		eventBus.register(coxChatCensor);
		collectionLogOverlay.setReleasedFullyOpenListener(this::onReleasedPopupFullyOpen);
		overlayManager.add(collectionLogOverlay);
		localDropRateDatasetLoader.load();
		localRarityDatasetLoader.load();
		log.debug("Collection Log Showcase started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(itemIdResolver);
		eventBus.unregister(killCountTracker);
		eventBus.unregister(coxChatCensor);
		coxChatCensor.reveal();
		restoreNotificationTitle();
		// Unregistering stops new messages, but the tracker is a @Singleton - Guice returns this same
		// instance when the plugin is re-enabled, so the stored count has to be dropped explicitly.
		killCountTracker.reset();
		overlayManager.remove(collectionLogOverlay);
		collectionLogOverlay.clear();
		// Only ever undoes this plugin's own hide - never something the game hid.
		setNativePopupPaintHidden(false);
		log.debug("Collection Log Showcase stopped!");
	}

	/**
	 * Hides the game's own collection log popup. Reasserted every frame - the notification is rebuilt
	 * and resized throughout its open animation, which undoes a one-shot hide.
	 * <p>See "This Plugin: Native Popup & Screenshots" in AGENTS.md before changing what is hidden or
	 * touching the game's popup setting - both silently break users' screenshots.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender beforeRender)
	{
		// A held CoX popup is hidden in every style, Audio only included - showing it would give the
		// loot away before the chest.
		if (isHeldCoxNotification())
		{
			setNativePopupPaintHidden(true);
			return;
		}

		if (config.panelStyle() == PanelStyle.AUDIO_ONLY)
		{
			return;
		}

		if (!COLLECTION_LOG_NOTIFICATION_TITLE.equalsIgnoreCase(client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE)))
		{
			return;
		}

		setNativePopupPaintHidden(true);
	}

	/**
	 * Switching to Audio only mid-popup would otherwise leave the game's popup hidden until it closes.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!CONFIG_GROUP.equals(configChanged.getGroup()))
		{
			return;
		}

		if ("panelStyle".equals(configChanged.getKey()) && config.panelStyle() == PanelStyle.AUDIO_ONLY)
		{
			clientThread.invoke(() -> setNativePopupPaintHidden(false));
		}
		else if ("coxChatCensor".equals(configChanged.getKey()))
		{
			// Rebuilt so lines already in the chatbox follow the new setting straight away.
			clientThread.invoke(client::refreshChat);
		}

		if (isCoxSettingTurnedOn(configChanged) && isCoxCensorEnabled())
		{
			clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				coxCensorConflictWarning(), null));
		}
	}

	/**
	 * Only switching one on from off counts - "Only mine" to "Everyone's" was already on.
	 */
	private static boolean isCoxSettingTurnedOn(ConfigChanged configChanged)
	{
		switch (configChanged.getKey())
		{
			case "delayCoxPopupUntilChest":
				return Boolean.parseBoolean(configChanged.getNewValue());
			case "coxChatCensor":
				boolean wasOff = configChanged.getOldValue() == null || CoxChatCensorMode.OFF.name().equals(configChanged.getOldValue());
				return wasOff && !CoxChatCensorMode.OFF.name().equals(configChanged.getNewValue());
			default:
				return false;
		}
	}

	/**
	 * CoX Censor (cox-special-loot-hider) does what our CoX settings do, and with both on the popup
	 * shows and the screenshot is taken twice. False when it isn't installed.
	 */
	private boolean isCoxCensorEnabled()
	{
		return pluginManager.getPlugins().stream()
			.filter(plugin -> COX_CENSOR_PLUGIN_CLASS.equals(plugin.getClass().getName()))
			.anyMatch(pluginManager::isPluginEnabled);
	}

	/**
	 * Swaps the notification title while a held CoX popup is in its delay stage, which is when the
	 * Screenshot plugin reads it. Priority 1 runs this ahead of that plugin, so it sees the swapped
	 * title and skips the screenshot - ours is taken at the chest instead (see
	 * #onReleasedPopupFullyOpen). onScriptPostFired puts the title back straight after.
	 */
	@Subscribe(priority = 1)
	public void onScriptPreFired(ScriptPreFired scriptPreFired)
	{
		if (scriptPreFired.getScriptId() != ScriptID.NOTIFICATION_DELAY || spoofedNotificationTitle != null
			|| !(isHeldCoxNotification() || shouldDelayCollectionScreenshot()))
		{
			return;
		}

		spoofedNotificationTitle = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		client.setVarcStrValue(VarClientID.NOTIFICATION_TITLE, SPOOFED_NOTIFICATION_TITLE);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired scriptPostFired)
	{
		if (scriptPostFired.getScriptId() == ScriptID.NOTIFICATION_DELAY)
		{
			restoreNotificationTitle();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		GameState state = gameStateChanged.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			restoreNotificationTitle();
			coxChatCensor.reveal();
		}

		// LOGGED_IN refires after every region load and hop, so the flag keeps it to once per login.
		if (state == GameState.LOGIN_SCREEN)
		{
			coxCensorConflictWarned = false;
			inCoxRaid = false;
		}
		else if (state == GameState.LOGGED_IN && !coxCensorConflictWarned)
		{
			coxCensorConflictWarned = true;
			warnIfCoxCensorConflicts();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged varbitChanged)
	{
		if (varbitChanged.getVarbitId() != VarbitID.RAIDS_CLIENT_INDUNGEON)
		{
			return;
		}

		boolean nowInRaid = varbitChanged.getValue() == 1;
		if (nowInRaid && !inCoxRaid)
		{
			warnIfCoxCensorConflicts();
		}
		inCoxRaid = nowInRaid;
	}

	private void warnIfCoxCensorConflicts()
	{
		if (isAnyCoxSettingOn() && isCoxCensorEnabled())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", coxCensorConflictWarning(), null);
		}
	}

	private String coxCensorConflictWarning()
	{
		boolean chatCensorOff = config.coxChatCensor() == CoxChatCensorMode.OFF;
		return COX_CENSOR_CONFLICT_WARNING + (chatCensorOff ? COX_CHAT_CENSOR_HINT : "") + "</col>";
	}

	private boolean isAnyCoxSettingOn()
	{
		return config.delayCoxPopupUntilChest() || config.coxChatCensor() != CoxChatCensorMode.OFF;
	}

	/**
	 * @return true if the game's popup on screen is a CoX purple that ours is holding back until the
	 *         chest
	 */
	private boolean isHeldCoxNotification()
	{
		if (!config.delayCoxPopupUntilChest())
		{
			return false;
		}

		String title = spoofedNotificationTitle != null
			? spoofedNotificationTitle
			: client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		return COLLECTION_LOG_NOTIFICATION_TITLE.equalsIgnoreCase(title)
			&& CoxLootParser.notificationUnique(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN)) != null;
	}

	private boolean shouldDelayCollectionScreenshot()
	{
		return config.delayCollectionScreenshot() && config.panelStyle() != PanelStyle.AUDIO_ONLY
			&& client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != COLLECTION_NEW_ITEM_CHAT_ONLY
			&& COLLECTION_LOG_NOTIFICATION_TITLE.equalsIgnoreCase(client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE));
	}

	private void restoreNotificationTitle()
	{
		if (spoofedNotificationTitle == null)
		{
			return;
		}
		client.setVarcStrValue(VarClientID.NOTIFICATION_TITLE, spoofedNotificationTitle);
		spoofedNotificationTitle = null;
	}

	/**
	 * Stands in for the Screenshot plugin's collection log screenshot that was skipped at raid end.
	 * With the game set to "chat message only" that plugin took its own from the chat line instead,
	 * so another one here would only be a duplicate.
	 */
	private void onReleasedPopupFullyOpen(String itemName)
	{
		if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) == COLLECTION_NEW_ITEM_CHAT_ONLY)
		{
			return;
		}
		coxScreenshot.capture(itemName);
	}

	/**
	 * Dynamic children are toggled too - the frame is drawn as eight of them (its corners and edges),
	 * which keep painting on their own when only the parent is hidden.
	 */
	private void setNativePopupPaintHidden(boolean hidden)
	{
		for (int componentId : NATIVE_POPUP_PAINT_COMPONENTS)
		{
			Widget widget = client.getWidget(componentId);
			if (widget == null)
			{
				continue;
			}

			widget.setHidden(hidden);

			Widget[] children = widget.getDynamicChildren();
			if (children != null)
			{
				for (Widget child : children)
				{
					if (child != null)
					{
						child.setHidden(hidden);
					}
				}
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		PreviewTier previewTier = config.previewTier();
		boolean previewChanged = previewTier != previousPreviewTier;
		if (previewChanged)
		{
			// Dismiss whatever's showing/queued so the next state starts clean. A held preview item
			// also carries a stale notificationStartMillis, so its hold/fade timer (see
			// CollectionLogOverlay#advance) would otherwise resume from an unpredictable point.
			collectionLogOverlay.clear();
		}
		previousPreviewTier = previewTier;

		// Each selection plays once unless the user explicitly enables looping.
		if (previewTier != PreviewTier.NONE && (previewChanged || config.previewLoop()) && collectionLogOverlay.isIdle())
		{
			if (previewTier == PreviewTier.RANDOM)
			{
				testRandomDatasetItems(1, false);
			}
			else
			{
				testTierPreviewItem(previewTier);
			}
		}
	}

	/**
	 * Releases popups held by the "delay CoX popups until chest" option. A held item is deliberately
	 * session-only: nothing re-shows it after a client restart, which is accepted rather than worth
	 * a logout-release path, since the chest is opened within a minute or two in practice.
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded widgetLoaded)
	{
		for (int interfaceId : COX_LOOT_REVEAL_INTERFACES)
		{
			if (widgetLoaded.getGroupId() == interfaceId)
			{
				revealCoxLoot();
				return;
			}
		}
	}

	private void revealCoxLoot()
	{
		collectionLogOverlay.releaseHeld();
		coxChatCensor.reveal();
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if (chatMessage.getType() != ChatMessageType.GAMEMESSAGE && chatMessage.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		Matcher matcher = NEW_COLLECTION_LOG_ITEM.matcher(chatMessage.getMessage());
		if (matcher.matches())
		{
			String itemName = Text.removeTags(matcher.group(1));
			handleNewCollectionLogItem(null, itemName, true);
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted commandExecuted)
	{
		if (COX_SIMULATE_COMMAND.equalsIgnoreCase(commandExecuted.getCommand()))
		{
			simulateCoxLoot(String.join(" ", commandExecuted.getArguments()));
			return;
		}
		if (COX_OPEN_COMMAND.equalsIgnoreCase(commandExecuted.getCommand()))
		{
			revealCoxLoot();
			return;
		}
		if (!TEST_COMMAND.equalsIgnoreCase(commandExecuted.getCommand()))
		{
			return;
		}

		String[] args = commandExecuted.getArguments();
		if (args.length == 0)
		{
			testRandomDatasetItems(1, true);
			return;
		}

		if (args.length == 1)
		{
			try
			{
				int count = Integer.parseInt(args[0]);
				if (count <= 0)
				{
					log.debug("Count must be positive.");
					return;
				}
				testRandomDatasetItems(count, true);
				return;
			}
			catch (NumberFormatException e)
			{
				// Not a count - fall through and treat it as an item name instead.
			}
		}

		// Every token is part of the item name, trailing digits included - the log is full of names
		// like "Saradomin page 1", and a trailing number was once read as a kill count override,
		// which silently truncated them to an item that doesn't exist.
		String itemName = String.join(" ", args);
		handleNewCollectionLogItem(null, itemName, true);
	}

	/**
	 * Posts the chat lines a CoX completion produces, through the same handlers as the real ones.
	 * "::coxsim Twisted bow" is your own drop; "::coxsim Twisted bow Some Player" is a teammate's,
	 * which only gets the party and clan broadcasts - the game messages are only ever your own.
	 */
	private void simulateCoxLoot(String arguments)
	{
		String lowered = arguments.toLowerCase();
		String item = CoxLootParser.UNIQUES.stream()
			.filter(unique -> lowered.startsWith(unique.toLowerCase()))
			.max(Comparator.comparingInt(String::length))
			.orElse(null);
		if (item == null)
		{
			// <lt>/<gt> because a bare <...> is parsed as a chat tag and vanishes.
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Usage: ::coxsim <lt>CoX unique<gt> [player], e.g. ::coxsim Twisted bow. Uniques: "
					+ String.join(", ", CoxLootParser.UNIQUES), null);
			return;
		}

		String localName = client.getLocalPlayer() != null ? Text.removeTags(client.getLocalPlayer().getName()) : "You";
		String otherName = arguments.substring(item.length()).trim();
		String player = otherName.isEmpty() ? localName : otherName;

		client.addChatMessage(ChatMessageType.FRIENDSCHATNOTIFICATION, "",
			"<col=ef20ff>" + player + " - </col><col=ff0000>" + item + "</col>", null);
		client.addChatMessage(ChatMessageType.CLAN_MESSAGE, "",
			player + " received special loot from a raid: " + item + " (1,234,567 coins)", null);
		if (player.equalsIgnoreCase(localName))
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"<col=ef1020>Valuable drop: " + item + " (1,234,567 coins)</col>", null);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"New item added to your collection log: " + item, null);
		}
	}

	private void testRandomDatasetItems(int count, boolean holdCox)
	{
		List<Integer> itemIds = rarityResolver.randomItemIds(count);
		if (itemIds.isEmpty())
		{
			log.debug("No items available to test with - rarity dataset failed to load.");
			return;
		}
		if (itemIds.size() < count)
		{
			log.debug("Only {} distinct items available - showing all of them.", itemIds.size());
		}

		for (int itemId : itemIds)
		{
			int canonicalId = itemManager.canonicalize(itemId);
			String itemName = itemManager.getItemComposition(canonicalId).getName();
			handleNewCollectionLogItem(canonicalId, itemName, holdCox);
		}
	}

	private void testTierPreviewItem(PreviewTier tier)
	{
		Integer itemId = rarityResolver.randomItemIdForTier(tier);
		if (itemId == null)
		{
			log.debug("No {} tier items available to preview - rarity dataset failed to load, or no item of that tier exists.", tier);
			return;
		}

		int canonicalId = itemManager.canonicalize(itemId);
		String itemName = itemManager.getItemComposition(canonicalId).getName();
		// Preview never holds - the delay is about real loot, and a held preview would sit blank.
		handleNewCollectionLogItem(canonicalId, itemName, false);
	}

	private void handleNewCollectionLogItem(Integer knownItemId, String itemName, boolean holdCox)
	{
		if (knownItemId != null)
		{
			handleResolvedItem(knownItemId, itemName, "known", holdCox);
			return;
		}

		// Resolution is asynchronous - see ItemIdResolver.resolveIdByName javadoc.
		itemIdResolver.resolveIdByName(itemName, (itemId, source) -> handleResolvedItem(itemId, itemName, source.toString(), holdCox));
	}

	private void handleResolvedItem(int itemId, String itemName, String resolvedVia, boolean holdCox)
	{
		itemName = CollectionLogSlotNames.withoutMembershipSuffix(itemName);
		RarityResult result = rarityResolver.resolve(itemId, itemName);

		// Read now, right before display, rather than when the chat message first arrived -
		// resolution can be deferred by a tick or more (see ItemIdResolver).
		List<String> candidateSources = rarityResolver.tabsForItemName(itemName);
		KillCountTracker.RecentKill kill = killCountTracker.killCountFor(candidateSources);

		Integer killCount = kill != null ? kill.getKillCount() : null;
		KillCountKind killCountKind = kill != null ? kill.getKind() : null;
		String source = kill != null ? kill.getSource() : null;
		Integer secondaryCount = kill != null ? kill.getSecondaryCount() : null;

		// The drop rate dataset's source names don't always agree with the kill count's source name
		// (e.g. Barrows' kill count source is "Barrows chest", but its drop rate source is "Chest
		// (Barrows)") - so a source-scoped miss falls back to the item-name-wide lookup rather than
		// giving up, same as when there's no known source at all.
		// The source-scoped lookup carries the " (max)" twin's rate too where there is one, so a
		// scaling drop shows both ends rather than just the base (see DropRateResolver.SourceRate).
		DropRateResolver.SourceRate sourceRate = source != null ? dropRateResolver.dropRateFor(source, itemName) : null;
		if (sourceRate == null)
		{
			sourceRate = dropRateResolver.soleSourceRate(itemName);
		}
		Double dropProbability = sourceRate != null && sourceRate.getMaxProbability() == null
			? sourceRate.getProbability()
			: null;
		// A drop from more than one tracked source has no single rate to show - collect every
		// candidate instead so the overlay can display them all (see CollectionLogOverlay).
		// A single source with a rate range lands here too, not just a drop from several sources -
		// both render as a range, so the overlay needs no notion of which case it is.
		List<DropRateResolver.SourceRate> ambiguousDropRates = dropProbability != null
			? List.of()
			: sourceRate != null ? List.of(sourceRate) : dropRateResolver.dropRatesByItemName(itemName);

		log.debug("New collection log item '{}' (id {}, resolved via {}) resolved to {} (kill count {} {}, drop probability {}, ambiguous rates {})",
			itemName, itemId, resolvedVia, result, killCount, killCountKind, dropProbability, ambiguousDropRates);

		// Only settings previews get synthetic counts; real unlocks keep observed game data.
		if ("known".equals(resolvedVia) && !holdCox)
		{
			ThreadLocalRandom random = ThreadLocalRandom.current();
			int[] examples = {1, 7, 64, 312, 1_234, 12_345, 123_456};
			killCount = examples[random.nextInt(examples.length)];
			KillCountKind[] kinds = {KillCountKind.KILLS, KillCountKind.CHESTS,
				KillCountKind.COMPLETIONS, KillCountKind.RUMOURS};
			killCountKind = kinds[random.nextInt(kinds.length)];
			source = null;
			secondaryCount = null;
		}

		boolean held = holdCox && config.delayCoxPopupUntilChest() && CoxLootParser.isUnique(itemName);

		collectionLogOverlay.enqueue(itemName, result.getItemId(), result.getTier(), result.getPrice(), result.isHighAlch(),
			result.getCompPercent(), killCount, killCountKind, source,
			secondaryCount, dropProbability, ambiguousDropRates, held,
			!"known".equals(resolvedVia) && config.delayCollectionScreenshot() && config.panelStyle() != PanelStyle.AUDIO_ONLY);
	}

	@Provides
	@Singleton
	SoundManager provideSoundManager(AudioPlayer audioPlayer, CollectionLogShowcaseConfig config,
		ScheduledExecutorService executor)
	{
		return new SoundManager(audioPlayer, config, executor,
			() -> getPluginDirectory().joinSegment("sounds"));
	}

	@Provides
	CollectionLogShowcaseConfig provideConfig(ConfigManager configManager)
	{
		// Migrate before RuneLite materializes this plugin's default settings.
		SettingsMigration.migrate(configManager);
		return configManager.getConfig(CollectionLogShowcaseConfig.class);
	}
}

package com.iviystical.collectionlogshowcase;

/**
 * Bridges the wiki dataset's item names and the collection log slot names the unlock chat message
 * uses, in both directions.
 * <p>Shared by the completion and drop-rate datasets, which are both generated from the wiki and
 * both looked up by the name out of that message. See "This Plugin: Rarity Tiers" in AGENTS.md.
 */
public final class CollectionLogSlotNames
{
	private static final String PET_SUFFIX = " (pet)";

	// The charge-state suffix the log puts on a slot whose item is stored uncharged. The dataset
	// carries it on 11 entries (Scythe of Vitur, Tumeken's shadow, ...), always *instead of* the
	// plain name rather than alongside it - so where an entry is stored plain and the game sends the
	// suffixed form, as for Eye of Ayak, an exact lookup misses. Found by reading a client log.
	private static final String UNCHARGED_SUFFIX = " (uncharged)";

	private CollectionLogSlotNames()
	{
	}

	/** The client appends this marker to members items when previewing on a free world. */
	public static String withoutMembershipSuffix(String name)
	{
		String suffix = " (Members)";
		int cut = name.length() - suffix.length();
		return cut > 0 && name.regionMatches(true, cut, suffix, 0, suffix.length())
			? name.substring(0, cut) : name;
	}

	/**
	 * @return the slot name for a dataset item name carrying the wiki's " (pet)" disambiguator, or
	 *         {@code null} if it carries none. Gull is the only such entry - the log's slot, and so
	 *         the chat message, reads plain "Gull".
	 */
	public static String slotNameOrNull(String itemName)
	{
		int cut = itemName.length() - PET_SUFFIX.length();
		return cut > 0 && itemName.regionMatches(true, cut, PET_SUFFIX, 0, PET_SUFFIX.length())
			? itemName.substring(0, cut)
			: null;
	}

	/**
	 * The reverse of {@link #slotNameOrNull}: a name out of the chat message reduced to the one the
	 * dataset is keyed on, for a lookup that has already missed on the message's own wording.
	 *
	 * @return the dataset name for a slot name carrying a charge-state suffix the dataset does not,
	 *         or {@code null} if it carries none
	 */
	public static String datasetNameOrNull(String slotName)
	{
		int cut = slotName.length() - UNCHARGED_SUFFIX.length();
		return cut > 0 && slotName.regionMatches(true, cut, UNCHARGED_SUFFIX, 0, UNCHARGED_SUFFIX.length())
			? slotName.substring(0, cut)
			: null;
	}
}

package com.iviystical.collectionlogshowcase;

import net.runelite.client.config.ConfigManager;

/** Copy shared preferences once, without changing the upstream plugin's configuration. */
final class SettingsMigration
{
    static final String GROUP = "collection-log-showcase";
    static final String LEGACY = "collection-log-popup-enhanced";
    private static final String[] KEYS = {
        "rarityBasis", "valueUncommonThreshold", "valueRareThreshold", "valueVeryRareThreshold",
        "rightPanelStat", "bulkUnlockSfx", "showProgressBar", "compactShowOwnership",
        "compactShimmer", "compactTextColour", "overlayDisplaySeconds", "overlayScalePercent",
        "backgroundOpacity", "foregroundOpacity", "colourCaption",
        "delayCoxPopupUntilChest", "coxChatCensor"
    };

    static void initializePreview(ConfigManager manager)
    {
        if (manager.getConfiguration(GROUP, "previewInitialized") != null) { return; }
        manager.setConfiguration(GROUP, "previewTier", "NONE");
        manager.setConfiguration(GROUP, "previewLoop", false);
        manager.setConfiguration(GROUP, "previewInitialized", true);
    }

    static void migrate(ConfigManager manager)
    {
        // Also applies to existing Showcase profiles, which already completed the upstream migration.
        if (manager.getConfiguration(GROUP, "showKillCount") == null)
        {
            String previous = manager.getConfiguration(GROUP, "leftPanelStat");
            if (previous == null) { previous = manager.getConfiguration(LEGACY, "leftPanelStat"); }
            if (previous != null) { manager.setConfiguration(GROUP, "showKillCount", "KILL_COUNT".equals(previous)); }
        }
        if (manager.getConfiguration(GROUP, "settingsMigrated") != null) { return; }
        for (String key : KEYS) { copy(manager, key, key); }
        copy(manager, "soundEnabledCommon", "soundEnabled");
        copy(manager, "soundVolumeCommon", "soundVolume");
        if (manager.getConfiguration(GROUP, "panelStyle") == null)
        {
            String previous = manager.getConfiguration(LEGACY, "panelStyle");
            manager.setConfiguration(GROUP, "panelStyle", "AUDIO_ONLY".equals(previous) ? "AUDIO_ONLY" : "COMPACT");
        }
        manager.setConfiguration(GROUP, "settingsMigrated", true);
    }

    private static void copy(ConfigManager manager, String oldKey, String newKey)
    {
        if (manager.getConfiguration(GROUP, newKey) != null) { return; }
        String value = manager.getConfiguration(LEGACY, oldKey);
        if (value != null) { manager.setConfiguration(GROUP, newKey, value); }
    }
}

package com.iviystical.collectionlogshowcase.cox;

import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Hides CoX purples in chat until the reward chest is opened, then shows them again.
 * <p>Censoring is done in "chatFilterCheck", which runs every time the chatbox is built, by swapping
 * the string the script is about to draw. The stored messages are never touched, so revealing is
 * just forgetting what was tracked and rebuilding the chatbox - nothing can be left censored by a
 * missed restore, and other plugins reading ChatMessage still see the real text.
 * <p>Only the raid party's own broadcast starts tracking, which is what scopes censoring to the player's raid.
 */
@Slf4j
@Singleton
public class CoxChatCensor
{
	private static final String CHAT_FILTER_CHECK = "chatFilterCheck";

	private final Client client;
	private final CollectionLogShowcaseConfig config;

	// Party and clan broadcasts, keyed by standardised player name + item.
	private final Set<String> trackedBroadcasts = new HashSet<>();
	// The local player's own game messages carry no name, so they are tracked by item alone.
	private final Set<String> trackedOwnItems = new HashSet<>();

	@Inject
	CoxChatCensor(Client client, CollectionLogShowcaseConfig config)
	{
		this.client = client;
		this.config = config;
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		CoxChatCensorMode mode = config.coxChatCensor();
		if (mode == CoxChatCensorMode.OFF)
		{
			return;
		}

		String message = chatMessage.getMessage();
		// Clan broadcasts never start tracking - they also arrive for raids the player wasn't in.
		switch (chatMessage.getType())
		{
			case FRIENDSCHATNOTIFICATION:
				CoxLootParser.parsePartyLoot(message).ifPresent(loot -> trackBroadcast(loot, mode));
				break;
			case GAMEMESSAGE:
				if (CoxLootParser.isOwnLootGameMessage(message))
				{
					String item = CoxLootParser.findUnique(message);
					if (item != null)
					{
						trackedOwnItems.add(item);
					}
				}
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!CHAT_FILTER_CHECK.equals(event.getEventName()) || !isCensoring())
		{
			return;
		}

		int[] intStack = client.getIntStack();
		int intStackSize = client.getIntStackSize();
		Object[] objectStack = client.getObjectStack();
		int objectStackSize = client.getObjectStackSize();

		ChatMessageType type = ChatMessageType.of(intStack[intStackSize - 2]);
		String message = (String) objectStack[objectStackSize - 1];
		if (message == null)
		{
			return;
		}

		String censored = censor(type, message);
		if (censored != null)
		{
			objectStack[objectStackSize - 1] = censored;
		}
	}

	/**
	 * Shows every censored line again. Called when the chest (or anything else that reveals the
	 * loot) is opened, and on logout, hop and shutdown so nothing stays hidden into a new session.
	 */
	public void reveal()
	{
		boolean wasCensoring = isCensoring();
		trackedBroadcasts.clear();
		trackedOwnItems.clear();
		if (wasCensoring)
		{
			client.refreshChat();
		}
	}

	private boolean isCensoring()
	{
		return config.coxChatCensor() != CoxChatCensorMode.OFF
			&& (!trackedBroadcasts.isEmpty() || !trackedOwnItems.isEmpty());
	}

	/**
	 * @return the line to draw instead, or null to leave it as it is
	 */
	private String censor(ChatMessageType type, String message)
	{
		switch (type)
		{
			case FRIENDSCHATNOTIFICATION:
				return CoxLootParser.parsePartyLoot(message)
					.filter(this::isTracked)
					.map(loot -> CoxLootParser.censorItem(message, loot.getItem()))
					.orElse(null);
			case CLAN_MESSAGE:
			case CLAN_GUEST_MESSAGE:
			case CLAN_GIM_MESSAGE:
				Optional<CoxLootParser.LootBroadcast> broadcast = CoxLootParser.parseClanBroadcast(message);
				return broadcast.filter(this::isTracked).isPresent() ? CoxLootParser.censorAfterColon(message) : null;
			case GAMEMESSAGE:
				if (CoxLootParser.isOwnLootGameMessage(message) && trackedOwnItems.contains(CoxLootParser.findUnique(message)))
				{
					return CoxLootParser.censorAfterColon(message);
				}
				return null;
			default:
				return null;
		}
	}

	private void trackBroadcast(CoxLootParser.LootBroadcast loot, CoxChatCensorMode mode)
	{
		if (mode == CoxChatCensorMode.OWN && !isLocalPlayer(loot.getPlayer()))
		{
			return;
		}
		trackedBroadcasts.add(key(loot));
	}

	private boolean isTracked(CoxLootParser.LootBroadcast loot)
	{
		return trackedBroadcasts.contains(key(loot));
	}

	private boolean isLocalPlayer(String name)
	{
		Player local = client.getLocalPlayer();
		return local != null && local.getName() != null && Text.standardize(local.getName()).equals(Text.standardize(name));
	}

	private static String key(CoxLootParser.LootBroadcast loot)
	{
		return Text.standardize(loot.getPlayer()) + "|" + loot.getItem();
	}
}

package com.iviystical.collectionlogshowcase.cox;

/**
 * Whose CoX purples are hidden in chat until the reward chest is opened.
 */
public enum CoxChatCensorMode
{
	OFF("Off"),
	OWN("Only mine"),
	EVERYONE("Everyone's");

	private final String label;

	CoxChatCensorMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.iviystical.collectionlogshowcase.cox;

import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.client.util.Text;

/**
 * Recognises CoX purples in chat and notification text. Matching is by item name rather than by
 * fixed offsets, since the raid party and clan broadcasts wrap names in colour tags that move about.
 * <p>Adapted from riktenx's cox-special-loot-hider (BSD-2-Clause).
 */
public final class CoxLootParser
{
	public static final List<String> UNIQUES = List.of(
		"Dexterous prayer scroll",
		"Arcane prayer scroll",
		"Twisted buckler",
		"Dragon hunter crossbow",
		"Dinh's bulwark",
		"Ancestral hat",
		"Ancestral robe top",
		"Ancestral robe bottom",
		"Dragon claws",
		"Elder maul",
		"Kodai insignia",
		"Twisted bow"
	);

	// Longest first, so "Ancestral robe bottom" can never be read as a shorter name it contains.
	private static final String[] UNIQUES_BY_LENGTH = UNIQUES.stream()
		.sorted(Comparator.comparingInt(String::length).reversed())
		.toArray(String[]::new);

	private static final String CENSORED = "???";

	private static final Pattern CLAN_BROADCAST = Pattern.compile(
		"^(.+?) received (?:special loot from a raid|a drop|a new collection log item): (.+)$",
		Pattern.CASE_INSENSITIVE);

	private static final String COLLECTION_LOG_GAME_MESSAGE = "New item added to your collection log:";
	private static final String VALUABLE_DROP_GAME_MESSAGE = "Valuable drop:";
	private static final String NOTIFICATION_PREFIX = "New item:";

	private CoxLootParser()
	{
	}

	public static boolean isUnique(String itemName)
	{
		return UNIQUES.contains(itemName);
	}

	/**
	 * @return the CoX purple named anywhere in {@code message}, or null if there isn't one
	 */
	public static String findUnique(String message)
	{
		if (message == null)
		{
			return null;
		}
		String stripped = Text.removeTags(message);
		return Arrays.stream(UNIQUES_BY_LENGTH).filter(stripped::contains).findFirst().orElse(null);
	}

	/**
	 * The raid party's own broadcast, "Name - Item", sent as a friends chat notification.
	 */
	public static Optional<LootBroadcast> parsePartyLoot(String message)
	{
		String item = findUnique(message);
		if (item == null)
		{
			return Optional.empty();
		}

		String stripped = Text.removeTags(message).trim();
		int index = stripped.indexOf(" - " + item);
		if (index <= 0)
		{
			return Optional.empty();
		}
		return Optional.of(new LootBroadcast(stripped.substring(0, index).trim(), item));
	}

	/**
	 * Clan broadcasts: special loot, valuable drop and new collection log item.
	 */
	public static Optional<LootBroadcast> parseClanBroadcast(String message)
	{
		Matcher matcher = CLAN_BROADCAST.matcher(Text.removeTags(message).trim());
		if (!matcher.matches())
		{
			return Optional.empty();
		}

		String item = findUnique(matcher.group(2));
		return item == null ? Optional.empty() : Optional.of(new LootBroadcast(matcher.group(1).trim(), item));
	}

	/**
	 * The local player's own game messages that name the item - the collection log line and the
	 * valuable drop line.
	 */
	public static boolean isOwnLootGameMessage(String message)
	{
		String stripped = Text.removeTags(message);
		return stripped.contains(COLLECTION_LOG_GAME_MESSAGE) || stripped.contains(VALUABLE_DROP_GAME_MESSAGE);
	}

	/**
	 * Replaces the item in a "Name - Item" party broadcast.
	 */
	public static String censorItem(String message, String item)
	{
		return message.replace(item, CENSORED);
	}

	/**
	 * Replaces everything after the first colon - the item and, where there is one, its coin value,
	 * which would give the item away just as well. A trailing colour close tag is kept so the line
	 * still renders in its original colour.
	 */
	public static String censorAfterColon(String message)
	{
		int colon = message.indexOf(':');
		if (colon < 0)
		{
			return message;
		}
		String suffix = message.endsWith("</col>") ? "</col>" : "";
		return message.substring(0, colon + 1) + " " + CENSORED + suffix;
	}

	/**
	 * @return the item named in the native popup's main text ("New item:" followed by the name),
	 *         or null if it isn't a CoX purple
	 */
	public static String notificationUnique(String notificationMainText)
	{
		if (notificationMainText == null)
		{
			return null;
		}
		String stripped = Text.removeTags(notificationMainText).trim();
		if (stripped.regionMatches(true, 0, NOTIFICATION_PREFIX, 0, NOTIFICATION_PREFIX.length()))
		{
			stripped = stripped.substring(NOTIFICATION_PREFIX.length()).trim();
		}
		return findUnique(stripped);
	}

	@Value
	public static class LootBroadcast
	{
		String player;
		String item;
	}
}

package com.iviystical.collectionlogshowcase.cox;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.ImageCapture;

/**
 * Takes the collection log screenshot for a CoX purple once its popup shows at the chest, standing in
 * for the Screenshot plugin's own, which is skipped at raid end (see the plugin's native popup
 * handling). Same folder, file name and options as the Screenshot plugin, and only when that plugin
 * would have taken one itself.
 * <p>Adapted from riktenx's cox-special-loot-hider (BSD-2-Clause).
 */
@Singleton
public class CoxScreenshot
{
	private static final String SCREENSHOT_GROUP = "screenshot";
	private static final String SUB_DIRECTORY = "Collection Log";

	private final ImageCapture imageCapture;
	private final ConfigManager configManager;

	@Inject
	CoxScreenshot(ImageCapture imageCapture, ConfigManager configManager)
	{
		this.imageCapture = imageCapture;
		this.configManager = configManager;
	}

	/**
	 * @return true if the Screenshot plugin is on and set to capture collection log entries
	 */
	public boolean isEnabled()
	{
		return bool("runelite", "screenshotplugin", true) && bool(SCREENSHOT_GROUP, "collectionLogEntries", true);
	}

	public void capture(String itemName)
	{
		if (!isEnabled())
		{
			return;
		}

		imageCapture.takeScreenshot(SUB_DIRECTORY, "Collection log (" + itemName + ")",
			bool(SCREENSHOT_GROUP, "includeFrame", true),
			bool(SCREENSHOT_GROUP, "notifyWhenTaken", true),
			bool(SCREENSHOT_GROUP, "copyToClipboard", false));
	}

	private boolean bool(String group, String key, boolean defaultValue)
	{
		Boolean value = configManager.getConfiguration(group, key, Boolean.class);
		return value != null ? value : defaultValue;
	}
}

package com.iviystical.collectionlogshowcase.droprate;

import com.google.common.reflect.TypeToken;
import com.iviystical.collectionlogshowcase.CollectionLogSlotNames;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;

/**
 * Resolves how likely a collection log item was to drop from a given source, per kill, from a
 * dataset generated offline (see the osrs-collection-log-data repo's generate-drop-rates.py) and
 * fetched at runtime by {@link RemoteDropRateUpdater} (see its javadoc). Starts out empty until that
 * first fetch completes.
 */
@Slf4j
@Singleton
public class DropRateResolver
{
	static final Type DATASET_TYPE = new TypeToken<Map<String, Map<String, Double>>>()
	{
	}.getType();

	// A source stored as "X (max)" is not a separate source - it holds the other end of X's rate
	// range, for content whose rate varies with scale (raid party size, a Slayer superior, the
	// Sepulchre's deeper floors). Folded into X everywhere rather than listed on its own, which
	// would otherwise read as a second boss and suppress the single-rate case entirely.
	private static final String MAX_SOURCE_SUFFIX = " (max)";

	private volatile Map<String, Map<String, Double>> dropRatesBySource;

	@Inject
	public DropRateResolver()
	{
		this.dropRatesBySource = normalize(Map.of());
	}

	/**
	 * Replaces the dataset with a freshly fetched or cached copy - called by
	 * {@link RemoteDropRateUpdater} once it has a parsed, non-empty replacement. Safe to call from
	 * any thread; readers always see either the old or new dataset, never a partial one.
	 */
	void reload(Map<String, Map<String, Double>> raw)
	{
		dropRatesBySource = normalize(raw);
	}

	/**
	 * @param source the boss or monster name the kill count is being tracked against
	 * @param itemName the collection log item's display name
	 * @return the per-kill drop probability (0-1) of {@code itemName} from {@code source}, or null
	 *         if either isn't in the dataset
	 */
	public Double dropProbability(String source, String itemName)
	{
		Map<String, Double> itemRates = dropRatesBySource.get(source);
		if (itemRates == null)
		{
			return null;
		}

		return rateFor(itemRates, itemName);
	}

	/**
	 * @param source the boss or monster name the kill count is being tracked against
	 * @param itemName the collection log item's display name
	 * @return both ends of {@code itemName}'s rate range from {@code source} where the dataset gives
	 *         it a " (max)" twin, else the single rate, else null if either isn't in the dataset
	 */
	public SourceRate dropRateFor(String source, String itemName)
	{
		Double rate = dropProbability(source, itemName);
		if (rate == null)
		{
			return null;
		}
		return new SourceRate(source, rate, maxRateFor(source, itemName));
	}

	// The " (max)" twin's rate for the same item, or null where the source has no twin or the twin
	// doesn't list the item (most twins carry only the few items whose rate actually varies).
	private Double maxRateFor(String source, String itemName)
	{
		if (source.toLowerCase(Locale.ROOT).endsWith(MAX_SOURCE_SUFFIX))
		{
			return null;
		}
		Map<String, Double> maxRates = dropRatesBySource.get(source + MAX_SOURCE_SUFFIX);
		return maxRates != null ? rateFor(maxRates, itemName) : null;
	}

	/**
	 * @param itemName the collection log item's display name
	 * @return the per-kill drop probability (0-1) of {@code itemName}, searched across every source
	 *         in the dataset - used when there's no correlated kill to read a source from. Only
	 *         returns a value when the item maps to exactly one source; if it's a notable drop from
	 *         more than one at different rates, returns null rather than guessing - see
	 *         {@link #dropRatesByItemName(String)} to get all of them instead.
	 */
	public Double dropProbabilityByItemName(String itemName)
	{
		SourceRate only = soleSourceRate(itemName);
		// Null for a one-source item whose rate is a range, so the caller falls through to
		// dropRatesByItemName and renders both ends rather than silently showing only the base.
		return only != null && only.getMaxProbability() == null ? only.getProbability() : null;
	}

	/**
	 * @param itemName the collection log item's display name
	 * @return the single source's rate(s) where {@code itemName} is a notable drop from exactly one
	 *         source (a " (max)" twin counting as the same source), else null
	 */
	public SourceRate soleSourceRate(String itemName)
	{
		List<SourceRate> matches = dropRatesByItemName(itemName);
		return matches.size() == 1 ? matches.get(0) : null;
	}

	/**
	 * @param itemName the collection log item's display name
	 * @return every (source, drop probability) pair {@code itemName} is a notable drop for, across
	 *         the whole dataset - empty if none. Used to show all candidate rates for an item that's
	 *         ambiguous across sources, since {@link #dropProbabilityByItemName(String)} returns null
	 *         for those.
	 */
	public List<SourceRate> dropRatesByItemName(String itemName)
	{
		List<SourceRate> matches = new ArrayList<>();
		for (Map.Entry<String, Map<String, Double>> entry : dropRatesBySource.entrySet())
		{
			String source = entry.getKey();
			// Skipped rather than listed: it is the same source, and counting it separately would
			// make every scaling item look ambiguous across two bosses.
			if (source.toLowerCase(Locale.ROOT).endsWith(MAX_SOURCE_SUFFIX))
			{
				continue;
			}
			Double rate = rateFor(entry.getValue(), itemName);
			if (rate != null)
			{
				matches.add(new SourceRate(source, rate, maxRateFor(source, itemName)));
			}
		}
		return matches;
	}

	/**
	 * Keyed on the chat message's wording, which is the log's slot name - so a name the dataset
	 * stores without the slot's charge-state suffix needs a second try. See CollectionLogSlotNames.
	 */
	private static Double rateFor(Map<String, Double> itemRates, String itemName)
	{
		itemName = CollectionLogSlotNames.withoutMembershipSuffix(itemName);
		Double exact = itemRates.get(itemName);
		if (exact != null)
		{
			return exact;
		}
		String datasetName = CollectionLogSlotNames.datasetNameOrNull(itemName);
		return datasetName != null ? itemRates.get(datasetName) : null;
	}

	private static Map<String, Map<String, Double>> normalize(Map<String, Map<String, Double>> raw)
	{
		Map<String, Map<String, Double>> result = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		if (raw != null)
		{
			raw.forEach((source, items) ->
			{
				Map<String, Double> itemRates = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
				itemRates.putAll(items);
				// Aliased to the log's slot name as well, since callers key on the chat message's
				// wording rather than the item name (see CollectionLogSlotNames).
				items.forEach((itemName, rate) ->
				{
					String slotName = CollectionLogSlotNames.slotNameOrNull(itemName);
					if (slotName != null)
					{
						itemRates.putIfAbsent(slotName, rate);
					}
				});
				result.put(source, itemRates);
			});
		}
		return result;
	}

	@Value
	public static class SourceRate
	{
		String source;
		double probability;
		// The other end of the rate range, from the source's " (max)" twin, or null where it has
		// none. See MAX_SOURCE_SUFFIX.
		Double maxProbability;

		public SourceRate(String source, double probability)
		{
			this(source, probability, null);
		}

		public SourceRate(String source, double probability, Double maxProbability)
		{
			this.source = source;
			this.probability = probability;
			this.maxProbability = maxProbability;
		}

		/**
		 * @return every rate this source gives the item - one value, or two where it has a
		 *         " (max)" twin. Not ordered: "max" is the max *scale*, which for a couple of
		 *         items (Little Nightmare, Zalcano shard) is the rarer end, not the commoner one.
		 */
		public List<Double> probabilities()
		{
			return maxProbability != null ? List.of(probability, maxProbability) : List.of(probability);
		}
	}
}

package com.iviystical.collectionlogshowcase.droprate;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads {@link DropRateResolver}'s dataset from drop-rates.json, bundled in the plugin jar under
 * /data. See the osrs-collection-log-data repo's generate-drop-rates.py for how it's produced.
 */
@Slf4j
@Singleton
public class LocalDropRateDatasetLoader
{
	private static final String RESOURCE_PATH = "/data/drop-rates.json";

	private final DropRateResolver dropRateResolver;
	private final Gson gson;

	@Inject
	public LocalDropRateDatasetLoader(DropRateResolver dropRateResolver, Gson gson)
	{
		this.dropRateResolver = dropRateResolver;
		this.gson = gson;
	}

	public void load()
	{
		try (InputStream stream = LocalDropRateDatasetLoader.class.getResourceAsStream(RESOURCE_PATH))
		{
			if (stream == null)
			{
				log.warn("Bundled drop rate dataset {} not found", RESOURCE_PATH);
				return;
			}

			try (Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
			{
				Map<String, Map<String, Double>> parsed = gson.fromJson(reader, DropRateResolver.DATASET_TYPE);
				if (parsed == null || parsed.isEmpty())
				{
					log.warn("Bundled drop rate dataset {} was empty", RESOURCE_PATH);
					return;
				}
				dropRateResolver.reload(parsed);
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to load bundled drop rate dataset {}", RESOURCE_PATH, e);
		}
	}
}

package com.iviystical.collectionlogshowcase.killcount;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * What the number attached to an unlock counts, and the panel label that says so. Derived from the
 * chat wording rather than a per-boss table (see {@link KillCountTracker}), so a new activity picks
 * up the right label as long as it phrases its message like an existing one.
 * <p>Where the kind alone would leave the activity ambiguous, {@link #labelFor} names the source
 * instead - see AGENTS.md.
 * <p>Labels carry their own trailing space, matching the other panel stats. Keep them short: the
 * panel draws them in roughly 129px (see {@code CollectionLogOverlay#cornerTextMaxWidth}), which
 * "Beginner caskets: ", the widest, comes within 7px of. {@code KillCountLabelWidthTest} enforces
 * it.
 */
@Getter
@RequiredArgsConstructor
public enum KillCountKind
{
	/** The default, and the fallback for anything unrecognised. */
	KILLS("Kills: "),
	/** Chest openings, which name no verb at all ("Your Barrows chest count is:"). */
	CHESTS("Chests: "),
	/** Wintertodt and Zalcano ("Your subdued X count is:"). */
	SUBDUES("Subdues: "),
	/** The Gauntlet, and the raids' "Your completed X count is:" form. */
	COMPLETIONS("Completions: "),
	/** Hespori. */
	HARVESTS("Harvests: "),
	/** Yama, whose kills are tracked as a success count. */
	SUCCESSES("Successes: "),
	/** Barbarian Assault. */
	TICKETS("Tickets: "),
	/** Doom of Mokhaiotl delve 8+, the only delve depth the game emits a count message for. */
	DEEP_DELVES("Deep delves: "),
	/** Doom of Mokhaiotl below delve 8, where there is no count message - read from a varp instead. */
	DELVES("Delves: "),
	/** Doom of Mokhaiotl, both counts at once: "Delves (Deep): " / "55 (9)", or "6 (0)" with none. */
	DELVES_WITH_DEEP("Delves (Deep): "),
	/** Guardians of the Rift. */
	RIFTS("Rifts: "),
	/** Hallowed Sepulchre floor completions. */
	FLOORS("Floors: "),
	/** Hallowed Sepulchre Grand Hallowed Coffin openings. */
	COFFINS("Coffins: "),
	/** Hunter Guild rumours. */
	RUMOURS("Rumours: ");

	private static final String TREASURE_TRAILS_SUFFIX = " treasure trails";

	// Keyed on the lowercased tier: the tracker stores the difficulty word verbatim from chat
	// ("hard Treasure Trails"), so the casing there is the game's, not ours.
	private static final Map<String, String> CLUE_CASKET_LABELS = Map.of(
		"beginner", "Beginner caskets: ",
		"easy", "Easy caskets: ",
		"medium", "Medium caskets: ",
		"hard", "Hard caskets: ",
		"elite", "Elite caskets: ",
		"master", "Master caskets: ");

	// A table rather than a suffix strip of the source name: the raw names are far over the label
	// budget ("Tombs of Amascut: Expert Mode: " measures 216px), so each abbreviation is written to
	// fit. See AGENTS.md.
	private static final Map<String, String> RAID_LABELS = Map.ofEntries(
		Map.entry("chambers of xeric", "CoX completions: "),
		Map.entry("chambers of xeric challenge mode", "CoX CM: "),
		Map.entry("theatre of blood", "ToB completions: "),
		Map.entry("theatre of blood: entry mode", "ToB Entry: "),
		Map.entry("theatre of blood: hard mode", "ToB Hard Mode: "),
		Map.entry("tombs of amascut", "ToA completions: "),
		Map.entry("tombs of amascut: entry mode", "ToA Entry: "),
		Map.entry("tombs of amascut: expert mode", "ToA Expert: "));

	private final String label;

	/**
	 * @param source the correlated kill's source name, or null when no kill was correlated
	 * @return a label naming {@code source} where the generic one would leave the activity
	 *         ambiguous - clue tiers and raid difficulty modes - else {@link #getLabel()}. See
	 *         AGENTS.md for why only those two, and why the label names the casket opened rather
	 *         than the item's own tabs.
	 */
	public String labelFor(String source)
	{
		// Every qualifiable source arrives as COMPLETIONS, so no other kind can be re-labelled by a
		// chance collision with the tables.
		if (source == null || this != COMPLETIONS)
		{
			return label;
		}

		String normalized = source.toLowerCase(Locale.ROOT);
		if (normalized.endsWith(TREASURE_TRAILS_SUFFIX))
		{
			String tier = normalized.substring(0, normalized.length() - TREASURE_TRAILS_SUFFIX.length());
			return CLUE_CASKET_LABELS.getOrDefault(tier, label);
		}
		return RAID_LABELS.getOrDefault(normalized, label);
	}

	/**
	 * @return every label the panel can draw, for the width test that keeps them inside the budget
	 *         documented above.
	 */
	static Collection<String> allLabels()
	{
		List<String> labels = new ArrayList<>();
		for (KillCountKind kind : values())
		{
			labels.add(kind.label);
		}
		labels.addAll(CLUE_CASKET_LABELS.values());
		labels.addAll(RAID_LABELS.values());
		return labels;
	}
}

package com.iviystical.collectionlogshowcase.killcount;

import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Stores the kill count from the most recent "Your X count is: N" chat message, for the plugin to
 * attach to an unlock from the same kill.
 * <p>See "This Plugin: Kill Count Correlation" in AGENTS.md for why correlation is by name rather
 * than by time, and for the chat-wording quirks the patterns below handle.
 */
@Slf4j
@Singleton
public class KillCountTracker
{
	// "count " is left outside the post group on purpose, so that group holds only the verb.
	private static final Pattern KILL_COUNT_PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?"
			+ "(?<boss>.+?) "
			+ "(?<post>(?:kill|harvest|completion|success|Total Ticket) )?(?:count )?"
			+ "is: ?(?<kc>[0-9,]+)",
		Pattern.CASE_INSENSITIVE);

	// Activities that don't use the "count is:" form. Their source is never named in the message, so
	// it's hardcoded below - each string must match the collection log tab name exactly.
	private static final Pattern DEEP_DELVE_PATTERN =
		Pattern.compile("Deep delves completed: ?(?<kc>[0-9,]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern RIFTS_CLOSED_PATTERN =
		Pattern.compile("Amount of Rifts you have closed: ?(?<kc>[0-9,]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern SEPULCHRE_FLOOR_PATTERN =
		Pattern.compile("completed Floor [0-9] of the Hallowed Sepulchre! Total completions: ?(?<kc>[0-9,]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern SEPULCHRE_COFFIN_PATTERN =
		Pattern.compile("opened the Grand Hallowed Coffin ?(?<kc>[0-9,]+)", Pattern.CASE_INSENSITIVE);
	// The trailing "rumours for the Hunter Guild" is what keeps this off other "You have completed
	// N ..." messages, such as the clue scroll tally below.
	private static final Pattern HUNTER_RUMOUR_PATTERN = Pattern.compile(
		"completed (?<kc>[0-9,]+) rumours? for the Hunter Guild",
		Pattern.CASE_INSENSITIVE);

	// Clue scroll caskets: "You have completed 295 hard Treasure Trails." - except the very first
	// casket of a tier ever, which reads "You have completed 1 hard Treasure Trail." (singular, no
	// "s"). Only the difficulty word is captured; the tab name (always plural) is reconstructed from
	// it below rather than taken verbatim, so the singular form still resolves to the right tab.
	private static final Pattern CLUE_SCROLL_PATTERN = Pattern.compile(
		"You have completed (?<kc>[0-9,]+) (?<difficulty>[a-zA-Z]+) Treasure Trails?",
		Pattern.CASE_INSENSITIVE);

	// "Shared Treasure Trail Rewards" and "Scroll Cases" both pool items across every clue
	// difficulty in the dataset (no per-tier split), so any completed casket counts for them,
	// regardless of which tier it was.
	private static final String SHARED_TREASURE_TRAIL_REWARDS = "shared treasure trail rewards";
	private static final String SCROLL_CASES = "scroll cases";

	// The casket message never says the drop was a rare one, so these are matched by suffix, the
	// same way as the two pooled tabs above. See AGENTS.md.
	private static final String RARE_TAB_SUFFIX = " treasure trails (rare)";

	private static final String ARTICLE_PREFIX = "the ";

	private static final String DOOM_OF_MOKHAIOTL = "Doom of Mokhaiotl";
	private static final String GUARDIANS_OF_THE_RIFT = "Guardians of the Rift";
	private static final String HALLOWED_SEPULCHRE = "Hallowed Sepulchre";
	private static final String HUNTER_GUILD = "Hunter Guild";

	// The Sepulchre appears twice on purpose: floors and coffins are counted separately but share a
	// tab, so whichever message arrived last is the one that gets attached.
	private static final List<FixedSource> FIXED_SOURCES = List.of(
		new FixedSource(DEEP_DELVE_PATTERN, DOOM_OF_MOKHAIOTL, KillCountKind.DEEP_DELVES),
		new FixedSource(RIFTS_CLOSED_PATTERN, GUARDIANS_OF_THE_RIFT, KillCountKind.RIFTS),
		new FixedSource(SEPULCHRE_FLOOR_PATTERN, HALLOWED_SEPULCHRE, KillCountKind.FLOORS),
		new FixedSource(SEPULCHRE_COFFIN_PATTERN, HALLOWED_SEPULCHRE, KillCountKind.COFFINS),
		new FixedSource(HUNTER_RUMOUR_PATTERN, HUNTER_GUILD, KillCountKind.RUMOURS)
	);

	// Chat message name -> collection log tab name, where the two are genuinely different words.
	private static final Map<String, String> BOSS_ALIASES = Map.ofEntries(
		Map.entry("Dagannoth Rex", "Dagannoth Kings"),
		Map.entry("Dagannoth Prime", "Dagannoth Kings"),
		Map.entry("Dagannoth Supreme", "Dagannoth Kings"),
		Map.entry("Callisto", "Callisto and Artio"),
		Map.entry("Artio", "Callisto and Artio"),
		Map.entry("Venenatis", "Venenatis and Spindel"),
		Map.entry("Spindel", "Venenatis and Spindel"),
		Map.entry("Vet'ion", "Vet'ion and Calvar'ion"),
		Map.entry("Calvar'ion", "Vet'ion and Calvar'ion"),
		Map.entry("Branda the Fire Queen", "Royal Titans"),
		Map.entry("Eldric the Ice King", "Royal Titans"),
		Map.entry("Barrows chest", "Barrows Chests"),
		Map.entry("Lunar Chest", "Moons of Peril"),
		Map.entry("TzTok-Jad", "The Fight Caves"),
		Map.entry("TzKal-Zuk", "The Inferno")
	);

	// Whole-word match, so a boss merely containing "chest" doesn't qualify as a chest opening.
	private static final Pattern CHEST_SUFFIX_PATTERN =
		Pattern.compile("(?<![a-z])chests?$", Pattern.CASE_INSENSITIVE);

	// Both forms the game emits: the <col=...> tag and the @mes_hl_red@ macro. The two render
	// identically in the chatbox, so a pattern written against one silently never matches the other
	// - found by reading raw messages in a client log. See AGENTS.md.
	private static final Pattern COLOUR_MARKUP_PATTERN = Pattern.compile("<[^<>]*>|@[a-zA-Z0-9_]+@");

	// Only here for the Doom delve count below, which is the one count read from game state rather
	// than from a chat message.
	private final Client client;

	private String lastBoss;
	private int lastKillCount;
	private KillCountKind lastKind;

	@Inject
	public KillCountTracker(Client client)
	{
		this.client = client;
	}

	// HOPPING is excluded on purpose - a hop keeps the same character, and deferred loot legitimately
	// survives one. See AGENTS.md.
	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		GameState state = gameStateChanged.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.CONNECTION_LOST)
		{
			reset();
		}
	}

	// Also called from the plugin's shutDown: Guice hands back this same instance on re-enable, so
	// unregistering from the event bus alone would leave the old count waiting.
	public void reset()
	{
		lastBoss = null;
		lastKillCount = 0;
		lastKind = null;
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		// Every count message observed in game arrives on one of these two. Widening this gate is not
		// the fix for a count that isn't picked up - check the colour markup first. See AGENTS.md.
		if (chatMessage.getType() != ChatMessageType.GAMEMESSAGE
			&& chatMessage.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = COLOUR_MARKUP_PATTERN.matcher(chatMessage.getMessage()).replaceAll("");

		Matcher matcher = KILL_COUNT_PATTERN.matcher(message);
		if (matcher.find())
		{
			String boss = Text.removeTags(matcher.group("boss"));
			lastBoss = boss;
			lastKillCount = parseCount(matcher.group("kc"));
			lastKind = kindOf(matcher.group("pre"), matcher.group("post"), boss);
			return;
		}

		Matcher clueMatcher = CLUE_SCROLL_PATTERN.matcher(message);
		if (clueMatcher.find())
		{
			lastBoss = clueMatcher.group("difficulty") + " Treasure Trails";
			lastKillCount = parseCount(clueMatcher.group("kc"));
			lastKind = KillCountKind.COMPLETIONS;
			return;
		}

		for (FixedSource fixedSource : FIXED_SOURCES)
		{
			Matcher fixedMatcher = fixedSource.getPattern().matcher(message);
			if (fixedMatcher.find())
			{
				lastBoss = fixedSource.getSource();
				lastKillCount = parseCount(fixedMatcher.group("kc"));
				lastKind = fixedSource.getKind();
				return;
			}
		}
	}

	/**
	 * @return what the count represents. Anything unrecognised falls back to
	 *         {@link KillCountKind#KILLS}.
	 */
	private static KillCountKind kindOf(String pre, String post, String boss)
	{
		if (pre != null)
		{
			switch (pre.trim())
			{
				case "subdued":
					return KillCountKind.SUBDUES;
				case "completed":
				case "completion count for":
					return KillCountKind.COMPLETIONS;
				default:
					break;
			}
		}

		if (post != null)
		{
			switch (post.trim())
			{
				case "harvest":
					return KillCountKind.HARVESTS;
				case "completion":
					return KillCountKind.COMPLETIONS;
				case "success":
					return KillCountKind.SUCCESSES;
				case "Total Ticket":
					return KillCountKind.TICKETS;
				default:
					return KillCountKind.KILLS;
			}
		}

		// No verb at all. Chests are the only activities that word it this way, and matching on the
		// name rather than a per-boss table picks up a new one for free.
		return CHEST_SUFFIX_PATTERN.matcher(boss).find() ? KillCountKind.CHESTS : KillCountKind.KILLS;
	}

	private static int parseCount(String count)
	{
		return Integer.parseInt(count.replace(",", ""));
	}

	/**
	 * @param candidateSources every collection log tab the item appears on
	 * @return the most recent kill count if its boss name matches any of {@code candidateSources},
	 *         else the Doom delve count if this is a Doom item, else null. Matching is
	 *         case-insensitive, alias- and article-aware.
	 */
	public RecentKill killCountFor(Collection<String> candidateSources)
	{
		// Doom is checked first, unlike every other source: it is the one activity with two counts
		// worth showing at once, and the delve path carries both. A deep-delve chat message would
		// otherwise win and render the deep count alone, dropping the total the player also wants.
		RecentKill delveCount = delveCountFor(candidateSources);
		if (delveCount != null)
		{
			return delveCount;
		}
		return chatKillFor(candidateSources);
	}

	/**
	 * Doom below delve 8 emits no count message, so there is no stored kill for this to match - the
	 * count comes from a varp instead. See "This Plugin: Kill Count Correlation" in AGENTS.md.
	 */
	private RecentKill delveCountFor(Collection<String> candidateSources)
	{
		if (!candidateSources.contains(DOOM_OF_MOKHAIOTL))
		{
			return null;
		}

		int delves = client.getVarpValue(VarPlayerID.TOTAL_DOM_LEVELS);
		if (delves <= 0)
		{
			// 0 before the varps populate - e.g. a preview fired on the login screen. The overlay
			// omits the stat entirely on a null count, which beats rendering "Delves: 0".
			return null;
		}
		// 4807 counts every delve at any depth - confirmed in game, where it always equalled the sum
		// of the per-level buckets. The two halves of the display are meant to be disjoint ("91 (9)"
		// summing to 100), so the deep count comes out of the total rather than being counted twice.
		int deepDelves = deepDelveCount();
		// Clamped rather than subtracted blind: 4816 is unconfirmed (see AGENTS.md), and if it ever
		// holds something larger than the total this must not render a negative or corrupt the one
		// number that is verified.
		int shallowDelves = deepDelves <= delves ? delves - deepDelves : delves;
		if (deepDelves <= 0)
		{
			// No bracket at zero, so the plain "Delves: 15" covers both a player who has done none and
			// one whose deep count failed to read - 15 is their real delve total either way. The
			// combined form would instead promise a deep count and then assert it is zero, which is a
			// claim this cannot stand behind while 4816 is unconfirmed (see AGENTS.md).
			return new RecentKill(DOOM_OF_MOKHAIOTL, delves, KillCountKind.DELVES);
		}
		return new RecentKill(DOOM_OF_MOKHAIOTL, shallowDelves, KillCountKind.DELVES_WITH_DEEP, deepDelves);
	}

	/**
	 * The deep-delve (8+) count shown in brackets beside the total - zero where the player has none,
	 * never null. Read from a varp so it is populated from login rather than only in a session that
	 * completed one, falling back to the chat count - see AGENTS.md, which records 4816 as the
	 * unconfirmed part of this.
	 */
	private int deepDelveCount()
	{
		int deepDelves = client.getVarpValue(VarPlayerID.DOM_LEVEL_8_PLUS_COMPLETIONS);
		boolean haveChatCount = lastKind == KillCountKind.DEEP_DELVES && DOOM_OF_MOKHAIOTL.equals(lastBoss);
		// Only a player who has actually done a deep delve can settle whether 4816 holds the deep
		// total - it reads 0 either way on an account without one, so it cannot be confirmed locally
		// (see AGENTS.md). Logged only when a chat count is there to compare against, which is
		// exactly the case that decides it.
		if (haveChatCount)
		{
			log.debug("Doom deep delves: varp 4816 = {}, chat count = {} ({})",
				deepDelves, lastKillCount,
				deepDelves == lastKillCount ? "agree - 4816 confirmed"
					: deepDelves <= 0 ? "varp empty - chat fallback used" : "DISAGREE - 4816 is not the deep total");
		}
		if (deepDelves <= 0 && haveChatCount)
		{
			deepDelves = lastKillCount;
		}
		return Math.max(0, deepDelves);
	}

	private RecentKill chatKillFor(Collection<String> candidateSources)
	{
		if (lastBoss == null)
		{
			return null;
		}
		String normalizedBoss = normalize(lastBoss);
		String normalizedAlias = normalize(BOSS_ALIASES.getOrDefault(lastBoss, lastBoss));
		boolean matches = candidateSources.stream()
			.map(KillCountTracker::normalize)
			.anyMatch(source -> matchesSource(normalizedBoss, source)
				|| matchesSource(normalizedAlias, source)
				|| isClueWildcardMatch(source));
		if (!matches)
		{
			return null;
		}
		return new RecentKill(lastBoss, lastKillCount, lastKind);
	}

	// "Shared Treasure Trail Rewards", "Scroll Cases" and the three "(Rare)" tabs are all tabs
	// matchesSource can't reach: the first two aren't split by clue difficulty at all, and a "(Rare)"
	// tab name is longer than the name the casket message reconstructs, so a substring search for it
	// can never hit. Kept separate from matchesSource/BOSS_ALIASES, which are both about a single
	// fixed tab per source. See AGENTS.md.
	private boolean isClueWildcardMatch(String normalizedSource)
	{
		return lastKind == KillCountKind.COMPLETIONS
			&& lastBoss.endsWith("Treasure Trails")
			&& (normalizedSource.equals(SHARED_TREASURE_TRAIL_REWARDS)
				|| normalizedSource.equals(SCROLL_CASES)
				|| normalizedSource.endsWith(RARE_TAB_SUFFIX));
	}

	// Substring-with-word-boundaries rather than equality: the collection log doesn't track raid
	// difficulty suffixes separately ("tombs of amascut: expert mode"), and "corrupted gauntlet"
	// shares a tab with the base activity. Complements BOSS_ALIASES rather than replacing it.
	private static boolean matchesSource(String boss, String source)
	{
		if (boss.equals(source))
		{
			return true;
		}
		return Pattern.compile("(?<![a-z'])" + Pattern.quote(source) + "(?![a-z'])")
			.matcher(boss)
			.find();
	}

	// Only the definite article is stripped - no dataset tab name starts with "A "/"An ".
	private static String normalize(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		return lower.startsWith(ARTICLE_PREFIX) ? lower.substring(ARTICLE_PREFIX.length()) : lower;
	}

	@Value
	private static class FixedSource
	{
		Pattern pattern;
		String source;
		KillCountKind kind;
	}

	@Value
	public static class RecentKill
	{
		String source;
		int killCount;
		KillCountKind kind;
		// A second count shown in brackets beside the first, where the activity has two the player
		// cares about at once - Doom's deep delves against its total. Null for every other source.
		Integer secondaryCount;

		public RecentKill(String source, int killCount, KillCountKind kind)
		{
			this(source, killCount, kind, null);
		}

		public RecentKill(String source, int killCount, KillCountKind kind, Integer secondaryCount)
		{
			this.source = source;
			this.killCount = killCount;
			this.kind = kind;
			this.secondaryCount = secondaryCount;
		}
	}
}

package com.iviystical.collectionlogshowcase.overlay;

import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import com.iviystical.collectionlogshowcase.droprate.DropRateResolver;
import com.iviystical.collectionlogshowcase.killcount.KillCountKind;
import com.iviystical.collectionlogshowcase.rarity.RarityTier;
import com.iviystical.collectionlogshowcase.sound.SoundManager;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.DoubleSummaryStatistics;
import java.util.Iterator;
import java.util.List;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Setter;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.QuantityFormatter;

@Singleton
public class CollectionLogOverlay extends Overlay
{
	private static final int TOP_MARGIN = 2;
	private static final int RGB_MASK = 0xFFFFFF;
	private static final long FOLD_MILLIS = 550;
	private static final long ICON_POP_MILLIS = 400;
	private final Client client;
	private final ItemManager itemManager;
	private final CollectionLogShowcaseConfig config;
	private final SoundManager soundManager;
	private final java.util.function.LongSupplier clock;
	private final Deque<PendingItem> queue = new ArrayDeque<>();
	private PendingItem current;
	private long notificationStartMillis;
	private Point lastAutoLocation;
	private int panelWidth;
	private float backgroundOpacity;
	private float foregroundOpacity;
	@Setter
	private Consumer<String> releasedFullyOpenListener;

	@Inject
	public CollectionLogOverlay(Client client, ItemManager itemManager, CollectionLogShowcaseConfig config, SoundManager soundManager)
	{
		this(client, itemManager, config, soundManager, System::currentTimeMillis);
	}

	CollectionLogOverlay(Client client, ItemManager itemManager, CollectionLogShowcaseConfig config, SoundManager soundManager,
		java.util.function.LongSupplier clock)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
		this.soundManager = soundManager;
		this.clock = clock;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
		setMovable(true);
	}

	public void enqueue(String itemName, int itemId, RarityTier tier, long price, boolean highAlch,
		Double compPercent, Integer killCount, KillCountKind killCountKind, String killCountSource,
		Double dropProbability, List<DropRateResolver.SourceRate> ambiguousDropRates)
	{
		enqueue(itemName, itemId, tier, price, highAlch, compPercent, killCount, killCountKind,
			killCountSource, null, dropProbability, ambiguousDropRates);
	}

	public void enqueue(String itemName, int itemId, RarityTier tier, long price, boolean highAlch,
		Double compPercent, Integer killCount, KillCountKind killCountKind, String killCountSource,
		Integer secondaryKillCount, Double dropProbability, List<DropRateResolver.SourceRate> ambiguousDropRates)
	{
		enqueue(itemName, itemId, tier, price, highAlch, compPercent, killCount, killCountKind,
			killCountSource, secondaryKillCount, dropProbability, ambiguousDropRates, false);
	}

	/**
	 * @param held holds the item back until {@link #releaseHeld()} instead of showing it in turn -
	 *             see CollectionLogShowcasePlugin's CoX chest handling.
	 */
	public void enqueue(String itemName, int itemId, RarityTier tier, long price, boolean highAlch,
		Double compPercent, Integer killCount, KillCountKind killCountKind, String killCountSource,
		Integer secondaryKillCount, Double dropProbability, List<DropRateResolver.SourceRate> ambiguousDropRates,
		boolean held)
	{
		enqueue(itemName, itemId, tier, price, highAlch, compPercent, killCount, killCountKind,
			killCountSource, secondaryKillCount, dropProbability, ambiguousDropRates, held, false);
	}

	public void enqueue(String itemName, int itemId, RarityTier tier, long price, boolean highAlch,
		Double compPercent, Integer killCount, KillCountKind killCountKind, String killCountSource,
		Integer secondaryKillCount, Double dropProbability, List<DropRateResolver.SourceRate> ambiguousDropRates,
		boolean held, boolean screenshotPending)
	{
		// The overlay was fully idle right before this item arrived, so it's the first of a fresh
		// batch - the only one that plays a sound when bulkUnlockSfx is on. A held item can't claim
		// this: it shows later, so #releaseHeld works it out again at the point it's let through.
		boolean batchStart = !held && queue.isEmpty() && current == null;
		queue.addLast(new PendingItem(itemName, itemId, tier, price, highAlch, compPercent, killCount,
			killCountKind, killCountSource, secondaryKillCount, dropProbability, ambiguousDropRates, batchStart, held, false, screenshotPending));
	}

	public void clear()
	{
		queue.clear();
		current = null;
	}

	/**
	 * Lets every held item through, in the order it was unlocked.
	 */
	public void releaseHeld()
	{
		// Whether the first released item opens a batch can't be decided at enqueue time - items may
		// have come and gone while it was held - so it's recomputed here against the state now.
		boolean batchStart = current == null && queue.stream().allMatch(PendingItem::isHeld);
		for (PendingItem item : queue)
		{
			if (!item.isHeld())
			{
				continue;
			}
			item.setHeld(false);
			item.setReleased(true);
			item.setBatchStart(batchStart);
			batchStart = false;
		}
	}

	/**
	 * @return true if nothing is currently showing or queued - used to drive the preview mode loop
	 *         (see CollectionLogShowcasePlugin#onGameTick), which re-triggers a new random item
	 *         each time the previous one finishes.
	 */
	public boolean isIdle()
	{
		return current == null && queue.isEmpty();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long now = clock.getAsLong();
		// Still advanced in Audio only: the queue is what plays and spaces out the sounds.
		advance(now);
		if (config.panelStyle() == PanelStyle.AUDIO_ONLY)
		{
			return null;
		}

		panelWidth = Math.round(320 * config.overlayScalePercent() / 100f);
		backgroundOpacity = config.backgroundOpacity() / 100f;
		foregroundOpacity = config.foregroundOpacity() / 100f;

		// Compared by value, not identity: an alt-click that doesn't move still saves our own point.
		Point placed = getPreferredLocation();
		boolean userPlaced = getPreferredPosition() != null || (placed != null && !placed.equals(lastAutoLocation));
		if (!userPlaced)
		{
			// Centers on the viewport rect, not the canvas: fixed/classic offsets it left of the sidebar,
			// and the Fixed Resizable Hybrid plugin narrows it in resizable mode.
			int viewportWidth = client.getViewportWidth();
			int viewportCenterX = viewportWidth > 0
				? client.getViewportXOffset() + viewportWidth / 2
				: client.getRealDimensions().width / 2;
			lastAutoLocation = new Point(viewportCenterX - (panelWidth / 2), TOP_MARGIN);
			setPreferredLocation(lastAutoLocation);
		}

		if (current == null)
		{
			// Report the panel's real width instead of 0 - RuneLite's positioning centers each frame
			// using the *previous* frame's bounds, so returning 0 here would make the panel jump left
			// once its real width is reported on the next frame it's shown.
			return new Dimension(panelWidth, 0);
		}

		return renderCompact(graphics, now - notificationStartMillis);
	}

	private Dimension renderCompact(Graphics2D original, long elapsed)
	{
		float scale = config.overlayScalePercent() / 100f;
		long fadeStart = FOLD_MILLIS + ICON_POP_MILLIS + config.overlayDisplaySeconds() * 1000L;
		float exitT = clamp01((elapsed - fadeStart) / (float) Math.max(200, config.fadeOutMillis()));
		Stat left = config.showKillCount() ? resolveStat(PanelStat.KILL_COUNT, current) : null;
		boolean showExtra = left != null;
		Stat chance = resolveStat(PanelStat.DROP_RATE, current);
		String rate = chance == null ? "Rate unknown" : (current.getDropProbability() == null ? "Rate range " : "") + String.join(" / ", chance.getValueLines());
		Double ownership = config.compactShowOwnership() ? current.getCompPercent() : null;
		String detail = compactDetail(rate, current.getPrice(), current.isHighAlch(), ownership,
			config.rightPanelStat() == RightPanelStat.VALUE);
		Font statsFont = FontManager.getRunescapeBoldFont().deriveFont(16f);
		boolean wrapStats = original.getFontMetrics(statsFont).stringWidth(detail) > 243;
		int height = 80 + (showExtra ? 18 : 0) + (wrapStats ? 18 : 0);
		long animationTime = elapsed <= fadeStart ? elapsed
			: Math.round((1 - exitT) * (FOLD_MILLIS + ICON_POP_MILLIS));
		float reveal = smoothReveal((animationTime - 180) / 500f);
		Graphics2D g = (Graphics2D) original.create();
		try
		{
			g.scale(scale, scale);

			int openingWidth = 58 + Math.round(262 * reveal);
			g.clipRect(0, 0, openingWidth, height);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_DEFAULT);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			Color accent = tierColor(current.getTier());
			float alpha = smoothReveal(animationTime / 180f);
			g.setComposite(AlphaComposite.SrcOver.derive(alpha * backgroundOpacity));
			g.setColor(new Color(24, 24, 23));
			g.fillRoundRect(0, 0, openingWidth, height, 4, 4);
			if (config.showGlow())
			{
				// Feather the glow inward so it stays inside the overlay's allocated bounds.
				for (int inset = 0; inset < 8; inset++)
				{
					float strength = .28f * (float) Math.pow(1 - inset / 8f, 2);
					g.setComposite(AlphaComposite.SrcOver.derive(alpha * foregroundOpacity * strength));
					g.setColor(accent);
					g.drawRoundRect(inset, inset, openingWidth - 1 - 2 * inset,
						height - 1 - 2 * inset, 5, 5);
				}
			}
			g.setComposite(AlphaComposite.SrcOver.derive(alpha * foregroundOpacity));
			g.setColor(new Color(73, 70, 63));
			g.drawRoundRect(0, 0, openingWidth - 1, height - 1, 4, 4);
			g.setColor(accent);
			g.drawLine(1, 1, openingWidth - 2, 1);
			g.setColor(new Color(83, 78, 66));
			g.drawLine(56, 8, 56, height - 9);
			// A travelling highlight follows the expanding edge and fades before the hold.
			float glint = 1 - smoothReveal((animationTime - 620) / 260f);
			if (glint > 0)
			{
				g.setComposite(AlphaComposite.SrcOver.derive(alpha * foregroundOpacity * glint));
				g.setColor(new Color(255, 238, 185));
				g.fillRect(openingWidth - 3, 3, 2, height - 6);
			}
			float itemReveal = smoothReveal(animationTime / 300f);
			BufferedImage sprite = current.getItemId() >= 0 ? itemManager.getImage(current.getItemId()) : null;
			if (sprite != null)
			{
				Graphics2D item = (Graphics2D) g.create();
				try
				{
					item.setComposite(AlphaComposite.SrcOver.derive(alpha * foregroundOpacity * itemReveal));
					item.translate(0, Math.round(-10 * (1 - itemReveal)));
					item.drawImage(sprite, 31 - sprite.getWidth() / 2, height / 2 - sprite.getHeight() / 2, null);
				}
				finally { item.dispose(); }
			}
			float textReveal = smoothReveal((animationTime - 380) / 400f);
			g.setComposite(AlphaComposite.SrcOver.derive(alpha * foregroundOpacity * textReveal));
			g.translate(0, Math.round(7 * (1 - textReveal)));
			Font small = FontManager.getRunescapeBoldFont().deriveFont(16f);
			Font title = FontManager.getRunescapeBoldFont().deriveFont(22f);
			g.setFont(small);
			compactText(g, "Collection log", 64, 20, opaque(config.colourCaption()));
			String tier = current.getTier().getLabel();
			compactText(g, tier, 307 - g.getFontMetrics().stringWidth(tier), 20, accent);
			FittedName name = fitName(g, current.getItemName(), title, 243, 16f);
			g.setFont(name.getFont());
			compactText(g, name.getText(), 64, 44, opaque(config.compactTextColour()));
			Font detailFont = small;
			FittedName fitted = fitName(g, wrapStats ? rate : detail, detailFont, 243, 14f);
			g.setFont(fitted.getFont());
			compactText(g, fitted.getText(), 64, 65, opaque(config.compactTextColour()));
			if (wrapStats)
			{
				String remaining = compactDetail("", current.getPrice(), current.isHighAlch(), ownership,
					config.rightPanelStat() == RightPanelStat.VALUE).trim();
				FittedName rest = fitName(g, remaining, detailFont, 243, 14f);
				g.setFont(rest.getFont());
				compactText(g, rest.getText(), 64, 83, opaque(config.compactTextColour()));
			}

			g.setFont(small);
			if (showExtra)
			{
				String extra = left.getLabel().trim() + " " + String.join(" / ", left.getValueLines());
				compactText(g, truncate(g, extra, small, 243), 64, wrapStats ? 101 : 83, opaque(config.compactTextColour()));
			}
			if (config.showProgressBar())
			{
				int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
				int obtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
				g.setColor(new Color(52, 51, 47));
				g.fillRect(64, height - 6, 243, 2);
				g.setColor(accent);
				g.fillRect(64, height - 6, total > 0 ? Math.round(243 * clamp01(obtained / (float) total)) : 0, 2);
			}
			if (config.compactShimmer() && elapsed >= 650 && elapsed < 1550)
			{
				Graphics2D glass = (Graphics2D) g.create();
				try
				{
					glass.clip(new java.awt.geom.RoundRectangle2D.Float(1, 1, 318, height - 2, 4, 4));
					float t = (elapsed - 650) / 900f;
					float x = -100 + 520 * t;
					glass.setComposite(AlphaComposite.SrcOver.derive(alpha * foregroundOpacity));
					glass.setPaint(new java.awt.LinearGradientPaint(x, 0, x + 85, 35,
						new float[] {0f, .45f, .55f, 1f}, new Color[] {
							new Color(255, 255, 255, 0), new Color(255, 245, 225, 25),
							new Color(255, 255, 255, 48), new Color(255, 255, 255, 0)}));
					glass.fill(new java.awt.geom.Rectangle2D.Float(x - height * .42f, 1, 85 + height * .42f, height - 2));
				}
				finally { glass.dispose(); }
			}
		}
		finally { g.dispose(); }
		return new Dimension(panelWidth, Math.round(height * scale));
	}

	static String compactDetail(String rate, long price, boolean highAlch, Double ownership, boolean valueFirst)
	{
		String value = price > 0 ? formatValue(price) + " gp" + (highAlch ? " (HA)" : "") : "";
		String players = ownership == null ? "" : String.format(java.util.Locale.ROOT, "%.1f%% players", ownership);
		java.util.List<String> parts = new java.util.ArrayList<>();
		if (valueFirst && !value.isEmpty()) { parts.add(value); }
		if (!rate.isEmpty()) { parts.add(rate); }
		if (!players.isEmpty()) { parts.add(players); }
		if (!valueFirst && !value.isEmpty()) { parts.add(value); }
		return String.join("   ", parts);
	}

	private static float smoothReveal(float t)
	{
		float p = clamp01(t);
		return 1 - (1 - p) * (1 - p) * (1 - p);
	}

	private void compactText(Graphics2D g, String text, int x, int y, Color color)
	{
		// Rasterize at the final font size, as the original overlay does, rather than
		// transforming small glyphs through the banner's layout scaling.
		Graphics2D textGraphics = (Graphics2D) g.create();
		try
		{
			float scale = config.overlayScalePercent() / 100f;
			textGraphics.scale(1 / scale, 1 / scale);
			textGraphics.setFont(g.getFont().deriveFont(g.getFont().getSize2D() * scale));
			int px = Math.round(x * scale);
			int py = Math.round(y * scale);
			textGraphics.setColor(Color.BLACK);
			textGraphics.drawString(text, px + 1, py + 1);
			textGraphics.setColor(color);
			textGraphics.drawString(text, px, py);
		}
		finally { textGraphics.dispose(); }
	}

	private PendingItem pollFirstUnheld()
	{
		for (Iterator<PendingItem> it = queue.iterator(); it.hasNext(); )
		{
			PendingItem item = it.next();
			if (!item.isHeld())
			{
				it.remove();
				return item;
			}
		}
		return null;
	}

	private void advance(long now)
	{
		if (current == null)
		{
			current = pollFirstUnheld();
			if (current != null)
			{
				notificationStartMillis = now;
				// Fired here rather than at enqueue() time so playback is spaced out to match each
				// item's visual reveal, instead of a whole burst firing its sound at once.
				if (!config.bulkUnlockSfx() || current.isBatchStart())
				{
					soundManager.play(current.getTier());
				}
			}
			return;
		}

		// Fully open: the fold has finished and the icon has popped in.
		if ((current.isReleased() || current.isScreenshotPending())
			&& now - notificationStartMillis >= (config.delayCollectionScreenshot() ? 1500 : FOLD_MILLIS + ICON_POP_MILLIS))
		{
			current.setReleased(false);
			current.setScreenshotPending(false);
			if (releasedFullyOpenListener != null)
			{
				releasedFullyOpenListener.accept(current.getItemName());
			}
		}

		long totalMillis = FOLD_MILLIS + ICON_POP_MILLIS + config.overlayDisplaySeconds() * 1000L + Math.max(200, config.fadeOutMillis());
		if (now - notificationStartMillis >= totalMillis)
		{
			current = null;
		}
	}

	private static float clamp01(float value)
	{
		return Math.max(0f, Math.min(1f, value));
	}

	/** Fits item names within the compact banner without wrapping. */
	private static FittedName fitName(Graphics2D graphics, String text, Font baseFont, int maxWidth, float minFontSize)
	{
		Font font = baseFont;
		while (graphics.getFontMetrics(font).stringWidth(text) > maxWidth && font.getSize2D() > minFontSize)
		{
			font = font.deriveFont(font.getSize2D() - 1f);
		}

		return new FittedName(font, truncate(graphics, text, font, maxWidth));
	}

	private static String truncate(Graphics2D graphics, String text, Font font, int maxWidth)
	{
		FontMetrics metrics = graphics.getFontMetrics(font);
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}

		String ellipsis = "...";
		StringBuilder truncated = new StringBuilder(text);
		while (truncated.length() > 0 && metrics.stringWidth(truncated + ellipsis) > maxWidth)
		{
			truncated.setLength(truncated.length() - 1);
		}
		return truncated + ellipsis;
	}

	/**
	 * @return the label/value/color to draw for {@code stat}, or null if that stat isn't
	 *         applicable to {@code item} (e.g. no rarity data, or no kill count was detected).
	 */
	private Stat resolveStat(PanelStat stat, PendingItem item)
	{
		switch (stat)
		{
			case VALUE:
				String valueText = formatValue(item.getPrice()) + " gp" + (item.isHighAlch() ? " (HA)" : "");
				return new Stat("Value: ", List.of(valueText), opaque(config.compactTextColour()));
			case RARITY:
				if (item.getCompPercent() == null)
				{
					return null;
				}
				return new Stat("Obtained by: ", List.of(String.format("%.1f%%", item.getCompPercent())), opaque(config.compactTextColour()));
			case KILL_COUNT:
				if (item.getKillCount() == null)
				{
					return null;
				}
				String killCountText = QuantityFormatter.formatNumber(item.getKillCount());
				// The label names what was actually counted - kills, harvests, deep delves - or the
				// source itself where that would still be ambiguous, as for a clue tier or a raid
				// mode (see KillCountKind). Count and kind always arrive together, so the fallback is
				// only a guard against a future caller supplying one without the other.
				KillCountKind killCountKind = item.getKillCountKind() != null ? item.getKillCountKind() : KillCountKind.KILLS;
				if (item.getSecondaryKillCount() != null)
				{
					killCountText += " (" + QuantityFormatter.formatNumber(item.getSecondaryKillCount()) + ")";
				}
				return new Stat(killCountKind.labelFor(item.getKillCountSource()), List.of(killCountText), opaque(config.compactTextColour()));
			case DROP_RATE:
				if (item.getDropProbability() != null)
				{
					return new Stat("Drop rate: ", List.of(formatFraction(item.getDropProbability())), opaque(config.compactTextColour()));
				}
				// No single known rate - show the rarest-to-most-common range across every tracked
				// source instead of hiding the stat, regardless of how many sources there are.
				List<DropRateResolver.SourceRate> ambiguous = item.getAmbiguousDropRates();
				if (ambiguous.isEmpty())
				{
					return null;
				}
				// Both ends of every candidate, so a source with a " (max)" twin contributes its
				// range rather than only its base rate.
				DoubleSummaryStatistics stats = ambiguous.stream()
					.flatMap(rate -> rate.probabilities().stream())
					.mapToDouble(Double::doubleValue)
					.summaryStatistics();
				// Ordered by rate, not by which end the dataset calls "max" - for a couple of items
				// (Little Nightmare, Zalcano shard) the max-scale rate is the rarer one, so taking
				// the data's own order would render a range that reads backwards.
				double commonest = stats.getMax();
				double rarest = stats.getMin();
				// Commonest first: the denominators then run upwards ("1/540 - 1/1350"), which is
				// how a rate range is written everywhere else.
				if (commonest == rarest)
				{
					return new Stat("Drop rate: ", List.of(formatFraction(commonest)), opaque(config.compactTextColour()));
				}
				// Exact digits by default; the compact form is only reached if the exact one would
				// run under the icon, which the widest real range does by a few px.
				String rangeText = formatFraction(commonest) + " - " + formatFraction(rarest);
				String compactRangeText = formatCompactFraction(commonest) + " - " + formatCompactFraction(rarest);
				return new Stat("Drop rate: ", List.of(rangeText), opaque(config.compactTextColour()),
					List.of(compactRangeText));
			case NONE:
			default:
				return null;
		}
	}

	private static String formatFraction(double dropProbability)
	{
		return "1/" + formatDenominator(Math.round(1 / dropProbability));
	}

	// Same fraction, fewer characters: a 4-digit denominator becomes one decimal of k ("1/1232" ->
	// "1/1.2k"), which is what buys the width back on a range. Only used when the exact form would
	// overflow, so the precision is lost on the few widest ranges rather than on every one.
	private static String formatCompactFraction(double dropProbability)
	{
		long denominator = Math.round(1 / dropProbability);
		if (denominator < 1000 || denominator >= 10_000)
		{
			return "1/" + formatDenominator(denominator);
		}
		String thousands = BigDecimal.valueOf(denominator, 3)
			.setScale(1, RoundingMode.HALF_UP)
			.stripTrailingZeros()
			.toPlainString();
		return "1/" + thousands + "k";
	}

	// Panel width doesn't fit long denominators (e.g. "1/313168") without clipping, so anything at or
	// above 10k is truncated to the nearest thousand - approximate rarity is all this stat is for.
	private static String formatDenominator(long denominator)
	{
		if (denominator < 10_000)
		{
			return Long.toString(denominator);
		}
		return (denominator / 1000) + "k";
	}

	// One decimal for thousands/millions, two for billions; omit insignificant zeroes.
	static String formatValue(long value)
	{
		BigDecimal amount = BigDecimal.valueOf(value).abs();
		if (amount.compareTo(BigDecimal.valueOf(1000)) < 0) { return Long.toString(value); }
		String[] suffixes = {"k", "m", "b"};
		long[] units = {1_000L, 1_000_000L, 1_000_000_000L};
		for (int i = 0; i < units.length; i++)
		{
			BigDecimal rounded = amount.divide(BigDecimal.valueOf(units[i]), i == 2 ? 2 : 1, RoundingMode.HALF_UP);
			if (i == 2 || rounded.compareTo(BigDecimal.valueOf(1000)) < 0)
			{
				return (value < 0 ? "-" : "") + rounded.stripTrailingZeros().toPlainString() + suffixes[i];
			}
		}
		throw new IllegalStateException("No GP unit selected");
	}

	/**
	 * The item name and progress fill colour: the tier colour, or plain white on the neutral style.
	 */
	private Color tierColor(RarityTier tier)
	{
		switch (tier)
		{
			case COMMON:
				return new Color(0xFFFFFF);
			case UNCOMMON:
				return new Color(0x1888C9);
			case RARE:
				return new Color(0x8431A6);
			case VERY_RARE:
				return new Color(0xB19F3B);
			case PET:
				return new Color(0xDC2367);
			default:
				return new Color(0xFFFFFF);
		}
	}

	/**
	 * Drops any alpha the colour picker allowed the user to dial in - see {@link #RGB_MASK}.
	 */
	private static Color opaque(Color color)
	{
		return color.getAlpha() == 0xFF ? color : new Color(color.getRGB() & RGB_MASK);
	}

	// Not @Value like the others here: #releaseHeld rewrites batchStart, held and released after
	// construction, so only those carry a setter and the rest stay read-only.
	@Getter
	@AllArgsConstructor
	private static class PendingItem
	{
		private final String itemName;
		private final int itemId;
		private final RarityTier tier;
		private final long price;
		private final boolean highAlch;
		private final Double compPercent;
		private final Integer killCount;
		private final KillCountKind killCountKind;
		private final String killCountSource;
		// Shown in brackets beside killCount where the activity has two counts at once - Doom's
		// deep delves against its total. Null for every other source.
		private final Integer secondaryKillCount;
		private final Double dropProbability;
		private final List<DropRateResolver.SourceRate> ambiguousDropRates;
		@Setter
		private boolean batchStart;
		@Setter
		private boolean held;
		// Let through by #releaseHeld and not yet reported to releasedFullyOpenListener.
		@Setter
		private boolean released;
		@Setter
		private boolean screenshotPending;
	}

	@Value
	private static class FittedName
	{
		Font font;
		String text;
	}

	@Value
	private static class Stat
	{
		String label;
		List<String> valueLines;
		Color valueColor;
		// A shorter rendering of the same value, used only when valueLines would not fit (see
		// drawCornerStat). Null where there is no shorter form worth showing.
		List<String> compactValueLines;

		Stat(String label, List<String> valueLines, Color valueColor)
		{
			this(label, valueLines, valueColor, null);
		}

		Stat(String label, List<String> valueLines, Color valueColor, List<String> compactValueLines)
		{
			this.label = label;
			this.valueLines = valueLines;
			this.valueColor = valueColor;
			this.compactValueLines = compactValueLines;
		}
	}
}

