package com.iviystical.collectionlogshowcase;

import com.iviystical.collectionlogshowcase.cox.CoxChatCensorMode;
import com.iviystical.collectionlogshowcase.overlay.PanelStyle;
import com.iviystical.collectionlogshowcase.sound.CollectionVoice;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

public class SettingsMigrationTest
{
    @Test
    public void firstActivationDisablesPreviewAndLoopWithoutImportingLegacyPreview()
    {
        ConfigManager manager = mock(ConfigManager.class);
        when(manager.getConfiguration(SettingsMigration.LEGACY, "previewTier")).thenReturn("RANDOM");
        SettingsMigration.migrate(manager);
        verify(manager, never()).setConfiguration(SettingsMigration.GROUP, "previewTier", "RANDOM");
        SettingsMigration.initializePreview(manager);
        verify(manager).setConfiguration(SettingsMigration.GROUP, "previewTier", "NONE");
        verify(manager).setConfiguration(SettingsMigration.GROUP, "previewLoop", false);
        verify(manager).setConfiguration(SettingsMigration.GROUP, "previewInitialized", true);
    }

    @Test
    public void laterActivationsPreserveExplicitPreviewChoices()
    {
        ConfigManager manager = mock(ConfigManager.class);
        when(manager.getConfiguration(SettingsMigration.GROUP, "previewInitialized")).thenReturn("true");
        SettingsMigration.initializePreview(manager);
        verify(manager, never()).setConfiguration(anyString(), anyString(), any());
    }

    @Test
    public void legacyStylesAndAudioMigrateWithoutWritingUpstream()
    {
        ConfigManager manager = mock(ConfigManager.class);
        when(manager.getConfiguration(SettingsMigration.LEGACY, "panelStyle")).thenReturn("NEUTRAL");
        when(manager.getConfiguration(SettingsMigration.LEGACY, "soundVolumeCommon")).thenReturn("42");
        when(manager.getConfiguration(SettingsMigration.LEGACY, "soundEnabledCommon")).thenReturn("false");
        when(manager.getConfiguration(SettingsMigration.LEGACY, "delayCoxPopupUntilChest")).thenReturn("true");
        SettingsMigration.migrate(manager);
        verify(manager).setConfiguration(SettingsMigration.GROUP, "panelStyle", "COMPACT");
        verify(manager).setConfiguration(SettingsMigration.GROUP, "soundVolume", "42");
        verify(manager).setConfiguration(SettingsMigration.GROUP, "soundEnabled", "false");
        verify(manager).setConfiguration(SettingsMigration.GROUP, "delayCoxPopupUntilChest", "true");
        verify(manager, never()).setConfiguration(eq(SettingsMigration.LEGACY), anyString(), any());
    }

    @Test
    public void migrationDoesNotOverwriteShowcaseSettingsAndOnlyRunsOnce()
    {
        ConfigManager manager = mock(ConfigManager.class);
        when(manager.getConfiguration(SettingsMigration.GROUP, "soundVolume")).thenReturn("80");
        when(manager.getConfiguration(SettingsMigration.LEGACY, "panelStyle")).thenReturn("AUDIO_ONLY");
        SettingsMigration.migrate(manager);
        verify(manager, never()).setConfiguration(eq(SettingsMigration.GROUP), eq("soundVolume"), any());
        verify(manager).setConfiguration(SettingsMigration.GROUP, "panelStyle", "AUDIO_ONLY");
        clearInvocations(manager);
        when(manager.getConfiguration(SettingsMigration.GROUP, "settingsMigrated")).thenReturn("true");
        SettingsMigration.migrate(manager);
        verify(manager, never()).setConfiguration(anyString(), anyString(), any());
    }

    @Test
    public void standaloneDefaultsKeepCoxOptInAndUseCEngineer()
    {
        CollectionLogShowcaseConfig config = new CollectionLogShowcaseConfig() {};
        assertEquals(2, PanelStyle.values().length);
        assertEquals(PanelStyle.COMPACT, config.panelStyle());
        assertEquals(CollectionVoice.C_ENGINEER, config.collectionVoice());
        assertTrue(config.soundEnabled());
        assertEquals(65, config.soundVolume());
        assertFalse(config.delayCoxPopupUntilChest());
        assertEquals(CoxChatCensorMode.OFF, config.coxChatCensor());
    }
}

package com.iviystical.collectionlogshowcase.cox;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Optional;
import org.junit.Test;

public class CoxLootParserTest
{
	@Test
	public void prefersTheLongestNameContained()
	{
		assertEquals("Ancestral robe bottom", CoxLootParser.findUnique("Ancestral robe bottom"));
		assertEquals("Twisted bow", CoxLootParser.findUnique("<col=ff0000>Twisted bow</col>"));
		assertNull(CoxLootParser.findUnique("Abyssal whip"));
	}

	@Test
	public void parsesThePartyBroadcast()
	{
		Optional<CoxLootParser.LootBroadcast> loot =
			CoxLootParser.parsePartyLoot("<col=ef20ff>Some Player - </col><col=ff0000>Elder maul</col>");
		assertEquals(Optional.of(new CoxLootParser.LootBroadcast("Some Player", "Elder maul")), loot);
		assertFalse(CoxLootParser.parsePartyLoot("<col=ef20ff>Special loot:</col>").isPresent());
	}

	@Test
	public void parsesEachClanBroadcast()
	{
		CoxLootParser.LootBroadcast expected = new CoxLootParser.LootBroadcast("Some Player", "Kodai insignia");
		assertEquals(Optional.of(expected), CoxLootParser.parseClanBroadcast(
			"Some Player received special loot from a raid: Kodai insignia (12,345,678 coins)."));
		assertEquals(Optional.of(expected), CoxLootParser.parseClanBroadcast(
			"Some Player received a drop: Kodai insignia (12,345,678 coins)."));
		assertEquals(Optional.of(expected), CoxLootParser.parseClanBroadcast(
			"Some Player received a new collection log item: Kodai insignia (123/1500)"));
		assertFalse(CoxLootParser.parseClanBroadcast("Some Player received a drop: Abyssal whip").isPresent());
	}

	@Test
	public void recognisesOwnLootGameMessages()
	{
		assertTrue(CoxLootParser.isOwnLootGameMessage("New item added to your collection log: Twisted bow"));
		assertTrue(CoxLootParser.isOwnLootGameMessage("<col=ef1020>Valuable drop: Twisted bow (1,234 coins)</col>"));
		assertFalse(CoxLootParser.isOwnLootGameMessage("Your completed Chambers of Xeric count is: 12."));
	}

	@Test
	public void censorsTheItemAndItsValue()
	{
		assertEquals("<col=ef20ff>Some Player - </col><col=ff0000>???</col>",
			CoxLootParser.censorItem("<col=ef20ff>Some Player - </col><col=ff0000>Dragon claws</col>", "Dragon claws"));
		assertEquals("New item added to your collection log: ???",
			CoxLootParser.censorAfterColon("New item added to your collection log: Dragon claws"));
		assertEquals("<col=ef1020>Valuable drop: ???</col>",
			CoxLootParser.censorAfterColon("<col=ef1020>Valuable drop: Dragon claws (5,000,000 coins)</col>"));
	}

	@Test
	public void readsTheNativePopupText()
	{
		assertEquals("Twisted bow", CoxLootParser.notificationUnique("New item:<br><col=ffffff>Twisted bow</col>"));
		assertNull(CoxLootParser.notificationUnique("New item:<br><col=ffffff>Abyssal whip</col>"));
		assertNull(CoxLootParser.notificationUnique(null));
	}
}

package com.iviystical.collectionlogshowcase.droprate;

import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * A source stored as "X (max)" holds the other end of X's rate range rather than being a source of
 * its own. Built inline rather than from the local-only fixture, which predates the convention.
 */
public class DropRateMaxSourceTest
{
	private DropRateResolver resolver;

	@Before
	public void before()
	{
		resolver = new DropRateResolver();
		resolver.reload(Map.of(
			"Doom of Mokhaiotl", Map.of("Avernic treads", 1 / 1350.0, "Demon tear", 1 / 15.0),
			"Doom of Mokhaiotl (max)", Map.of("Avernic treads", 1 / 540.0),
			// The inverted case: the max-scale rate is the rarer end, not the commoner one.
			"The Nightmare", Map.of("Little Nightmare", 1 / 800.0),
			"The Nightmare (max)", Map.of("Little Nightmare", 1 / 4000.0),
			// A second, unrelated source for one item, to keep the genuinely-ambiguous path covered.
			"Tekton", Map.of("Shared item", 1 / 100.0),
			"Zalcano", Map.of("Shared item", 1 / 200.0)));
	}

	@Test
	public void sourceScopedLookupCarriesBothEndsOfTheRange()
	{
		DropRateResolver.SourceRate rate = resolver.dropRateFor("Doom of Mokhaiotl", "Avernic treads");
		assertEquals(1 / 1350.0, rate.getProbability(), 1e-9);
		assertEquals(Double.valueOf(1 / 540.0), rate.getMaxProbability());
		assertEquals(List.of(1 / 1350.0, 1 / 540.0), rate.probabilities());
	}

	@Test
	public void anItemWithNoMaxTwinHasNoRange()
	{
		DropRateResolver.SourceRate rate = resolver.dropRateFor("Doom of Mokhaiotl", "Demon tear");
		assertNull(rate.getMaxProbability());
		assertEquals(List.of(1 / 15.0), rate.probabilities());
	}

	// The whole point of folding: without it the item looks like a drop from two different bosses,
	// which suppresses the single-rate case and names "Doom of Mokhaiotl (max)" as a source.
	@Test
	public void maxSourceIsNotListedAsASourceOfItsOwn()
	{
		List<DropRateResolver.SourceRate> rates = resolver.dropRatesByItemName("Avernic treads");
		assertEquals(1, rates.size());
		assertEquals("Doom of Mokhaiotl", rates.get(0).getSource());
		assertEquals(Double.valueOf(1 / 540.0), rates.get(0).getMaxProbability());
	}

	// A one-source item whose rate is a range must not collapse to its base rate - the caller needs
	// null here so it falls through to the range-rendering path.
	@Test
	public void singleRateIsNullForAnItemWhoseRateIsARange()
	{
		assertNull(resolver.dropProbabilityByItemName("Avernic treads"));
		assertEquals(1 / 15.0, resolver.dropProbabilityByItemName("Demon tear"), 1e-9);
	}

	@Test
	public void soleSourceRateStillReportsAGenuinelyAmbiguousItemAsAmbiguous()
	{
		assertNull(resolver.soleSourceRate("Shared item"));
		assertEquals(2, resolver.dropRatesByItemName("Shared item").size());
	}

	// "max" is the max scale, not the better rate - Little Nightmare is rarer at max scale.
	@Test
	public void anInvertedMaxRateIsStillCarried()
	{
		DropRateResolver.SourceRate rate = resolver.dropRateFor("The Nightmare", "Little Nightmare");
		assertEquals(Double.valueOf(1 / 4000.0), rate.getMaxProbability());
	}

	@Test
	public void queryingTheMaxSourceDirectlyDoesNotRecurse()
	{
		DropRateResolver.SourceRate rate = resolver.dropRateFor("Doom of Mokhaiotl (max)", "Avernic treads");
		assertEquals(1 / 540.0, rate.getProbability(), 1e-9);
		assertNull(rate.getMaxProbability());
	}
}

package com.iviystical.collectionlogshowcase.droprate;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.List;
import java.util.Map;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Loaded against the real dataset fixture below (see the osrs-collection-log-data repo's
 * generate-drop-rates.py). Abyssal Sire -> Unsired is a simple, verified 1/100 single-roll drop,
 * used here as a stable reference point.
 *
 * Uses the same bundled dataset shipped with the plugin; runs locally and in CI.
 */
public class DropRateResolverTest
{
	private static final String FIXTURE = "/data/drop-rates.json";

	private DropRateResolver resolver;

	@Before
	public void before()
	{
		resolver = new DropRateResolver();
		resolver.reload(loadFixture());
	}

	private static Map<String, Map<String, Double>> loadFixture()
	{
		InputStream stream = DropRateResolverTest.class.getResourceAsStream(FIXTURE);
		org.junit.Assert.assertNotNull("Bundled dataset " + FIXTURE + " must be present", stream);
		Gson gson = new Gson();
		try (Reader reader = new InputStreamReader(stream))
		{
			return gson.fromJson(reader, DropRateResolver.DATASET_TYPE);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	@Test
	public void unknownSourceReturnsNull()
	{
		assertNull(resolver.dropProbability("Not a real boss", "Some item"));
	}

	@Test
	public void knownSourceUnknownItemReturnsNull()
	{
		assertNull(resolver.dropProbability("Abyssal Sire", "Not a real item"));
	}

	@Test
	public void sourceLookupIsCaseInsensitive()
	{
		assertEquals(resolver.dropProbability("Abyssal Sire", "Unsired"),
			resolver.dropProbability("ABYSSAL SIRE", "Unsired"), 0.0001);
	}

	@Test
	public void itemLookupIsCaseInsensitive()
	{
		assertEquals(resolver.dropProbability("Abyssal Sire", "Unsired"),
			resolver.dropProbability("Abyssal Sire", "UNSIRED"), 0.0001);
	}

	// The chat message carries the log's slot name, which for some items adds a charge-state suffix
	// the dataset does not - "Eye of Ayak (uncharged)" against a plain "Eye of Ayak" entry. Without
	// the alias the drop rate misses alongside the kill count. See CollectionLogSlotNames.
	@Test
	public void unchargedSlotNameFallsBackToThePlainDatasetName()
	{
		assertEquals(resolver.dropProbability("Doom of Mokhaiotl", "Demon tear"),
			resolver.dropProbability("Doom of Mokhaiotl", "Demon tear (uncharged)"), 0.0001);
	}

	// An entry the dataset already stores *with* the suffix must still resolve under it.
	@Test
	public void datasetNamesThatCarryTheUnchargedSuffixStillResolve()
	{
		assertNotNull(resolver.dropProbability("Monumental chest", "Scythe of vitur (uncharged)"));
	}

	@Test
	public void knownDropRateMatchesWikiFraction()
	{
		assertEquals(0.01, resolver.dropProbability("Abyssal Sire", "Unsired"), 0.0001);
	}

	@Test
	public void itemNameLookupResolvesAnUnambiguousItem()
	{
		// Jar of souls only drops from Cerberus - single source, so this should resolve the same
		// as looking it up by source directly.
		assertEquals(resolver.dropProbability("Cerberus", "Jar of souls"),
			resolver.dropProbabilityByItemName("Jar of souls"), 0.0001);
	}

	@Test
	public void itemNameLookupReturnsNullForAnAmbiguousItem()
	{
		// Hydra tail drops from more than one real source (Alchemical Hydra, Colossal Hydra, Hydra)
		// at different rates - there's no single correct rate to show without knowing which one, so
		// this must return null rather than guessing.
		assertNull(resolver.dropProbabilityByItemName("Hydra tail"));
	}

	@Test
	public void dropRatesByItemNameReturnsEveryCandidateForAnAmbiguousItem()
	{
		List<DropRateResolver.SourceRate> matches = resolver.dropRatesByItemName("Hydra tail");
		assertEquals(3, matches.size());
		assertTrue(matches.stream().anyMatch(match -> match.getSource().equalsIgnoreCase("Alchemical Hydra")));
	}

	@Test
	public void dropRatesByItemNameReturnsSingleEntryForAnUnambiguousItem()
	{
		List<DropRateResolver.SourceRate> matches = resolver.dropRatesByItemName("Jar of souls");
		assertEquals(1, matches.size());
		assertEquals("Cerberus", matches.get(0).getSource());
	}

	@Test
	public void dropRatesByItemNameReturnsEmptyForAnUnknownItem()
	{
		assertTrue(resolver.dropRatesByItemName("Not a real item").isEmpty());
	}

	// The dataset carries the wiki's "Gull (pet)", but callers key on the chat message's plain
	// "Gull" - both must find the same rate.
	@Test
	public void petSuffixedItemIsFoundByItsSlotName()
	{
		assertEquals(resolver.dropProbability("Shellbane gryphon", "Gull (pet)"),
			resolver.dropProbability("Shellbane gryphon", "Gull"), 0.0000001);
		assertEquals(1, resolver.dropRatesByItemName("Gull").size());
	}
}

