	@Test
	public void parsesSingularHunterGuildRumourCount()
	{
		fireMessage("You have completed <col=ff0000>1</col> rumour for the Hunter Guild.");

		KillCountTracker.RecentKill kill = tracker.killCountFor(List.of("Hunter Guild"));
