	@Test
	public void parsesEachClueScrollDifficultyAgainstItsOwnTab()
	{
		fireMessage("You have completed 1 beginner Treasure Trails.");
		assertEquals(1, tracker.killCountFor(List.of("Beginner Treasure Trails")).getKillCount());

		fireMessage("You have completed 2 easy Treasure Trails.");
		assertEquals(2, tracker.killCountFor(List.of("Easy Treasure Trails")).getKillCount());

		fireMessage("You have completed 3 medium Treasure Trails.");
		assertEquals(3, tracker.killCountFor(List.of("Medium Treasure Trails")).getKillCount());

		fireMessage("You have completed 4 hard Treasure Trails.");
		assertEquals(4, tracker.killCountFor(List.of("Hard Treasure Trails")).getKillCount());

		fireMessage("You have completed 5 elite Treasure Trails.");
		assertEquals(5, tracker.killCountFor(List.of("Elite Treasure Trails")).getKillCount());

		fireMessage("You have completed 6 master Treasure Trails.");
		assertEquals(6, tracker.killCountFor(List.of("Master Treasure Trails")).getKillCount());
	}

	@Test
	public void latestOfTwoClueCompletionsInARowWins()
	{
		// Redeeming caskets back-to-back (e.g. a hard casket followed immediately by an elite one)
		// fires one completion message per casket - the item unlocks from whichever fired last.
		fireMessage("You have completed 295 hard Treasure Trails.");
		fireMessage("You have completed 126 elite Treasure Trails.");

		KillCountTracker.RecentKill kill = tracker.killCountFor(List.of("Elite Treasure Trails"));
		assertEquals(126, kill.getKillCount());

		assertNull(tracker.killCountFor(List.of("Hard Treasure Trails")));
	}

	@Test
	public void doesNotConfuseClueScrollTallyWithHunterRumours()
	{
		// Both start with "You have completed N ..." - the Hunter Guild pattern's trailing text is
		// what tells them apart, but the clue pattern must not accidentally swallow the rumour message.
		fireMessage("You have completed 312 rumours for the Hunter Guild.");

		assertNull(tracker.killCountFor(List.of("Master Treasure Trails")));
	}

	@Test
	public void parsesFirstEverCasketOfATierAsSingular()
	{
		// The very first casket of a tier reads "...1 master Treasure Trail." (no "s") - every later
		// one is plural. The stored source must still be the plural tab name either way.
		fireMessage("You have completed 1 master Treasure Trail.");

		KillCountTracker.RecentKill kill = tracker.killCountFor(List.of("Master Treasure Trails"));
		assertEquals("master Treasure Trails", kill.getSource());
		assertEquals(1, kill.getKillCount());
		assertEquals(KillCountKind.COMPLETIONS, kill.getKind());
	}

	@Test
	public void matchesSharedTreasureTrailRewardsForAnyDifficulty()
	{
		// The dataset pools "Shared Treasure Trail Rewards" across every clue tier rather than
		// splitting it per difficulty - any completed casket should count for it.
		fireMessage("You have completed 42 easy Treasure Trails.");

		KillCountTracker.RecentKill kill = tracker.killCountFor(List.of("Shared Treasure Trail Rewards"));
		assertEquals(42, kill.getKillCount());
		assertEquals(KillCountKind.COMPLETIONS, kill.getKind());
	}

	@Test
	public void matchesScrollCasesForAnyDifficulty()
	{
		// Same reasoning as Shared Treasure Trail Rewards - minor/major scroll cases for every tier
		// (plus the Mimic's) all share the one "Scroll Cases" tab.
		fireMessage("You have completed 8 elite Treasure Trails.");

		KillCountTracker.RecentKill kill = tracker.killCountFor(List.of("Scroll Cases"));
		assertEquals(8, kill.getKillCount());
		assertEquals(KillCountKind.COMPLETIONS, kill.getKind());
	}

	@Test
	public void matchesRareClueTabForItsOwnDifficulty()
	{
		// matchesSource looks for the source inside the boss name, and a "(Rare)" tab name is the
		// longer of the two - so it can never hit. Every item on these tabs is rare-only, with no
		// plain tab to fall back on.
		fireMessage("You have completed 295 hard Treasure Trails.");

		KillCountTracker.RecentKill kill = tracker.killCountFor(List.of("Hard Treasure Trails (Rare)"));
		assertEquals(295, kill.getKillCount());
		assertEquals(KillCountKind.COMPLETIONS, kill.getKind());
	}

	@Test
	public void matchesRareClueTabsAcrossDifficulties()
	{
		// Deliberately not tier-strict: most rare items sit on two or three of these tabs at once, so
		// strictness would change nothing for them while costing the count outright on a stale tier.
		fireMessage("You have completed 126 elite Treasure Trails.");

		assertEquals(126, tracker.killCountFor(List.of("Hard Treasure Trails (Rare)")).getKillCount());
		assertEquals(126, tracker.killCountFor(List.of("Master Treasure Trails (Rare)")).getKillCount());
	}

	@Test
	public void doesNotWildcardMatchRareClueTabsForUnrelatedCompletions()
	{
		// Same scoping as the pooled tabs - a raid's "completed X" count must not satisfy a clue tab.
		fireMessage("Your completed Chambers of Xeric count is: 5.");

		assertNull(tracker.killCountFor(List.of("Master Treasure Trails (Rare)")));
	}

	@Test
	public void doesNotWildcardMatchUnrelatedCompletions()
	{
		// The wildcard is scoped to sources ending in "Treasure Trails" - a raid's "completed X"
		// message must not accidentally satisfy Shared Treasure Trail Rewards or Scroll Cases.
		fireMessage("Your completed Chambers of Xeric count is: 5.");

		assertNull(tracker.killCountFor(List.of("Shared Treasure Trail Rewards")));
		assertNull(tracker.killCountFor(List.of("Scroll Cases")));
	}
}

package com.iviystical.collectionlogshowcase.overlay;

import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import com.iviystical.collectionlogshowcase.rarity.PreviewTier;
import com.iviystical.collectionlogshowcase.sound.SoundManager;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/** Horizontal drift of a few px isn't obvious in the drawn result, so assert the location directly. */
public class CollectionLogOverlayCenteringTest
{
	// BASE_PANEL_WIDTH at the 100% scale stubbed below.
	private static final int PANEL_WIDTH = 320;

	private Client client;
	private CollectionLogOverlay overlay;

	@Before
	public void before()
	{
		client = mock(Client.class);
		ItemManager itemManager = mock(ItemManager.class);
		CollectionLogShowcaseConfig config = mock(CollectionLogShowcaseConfig.class);
		SoundManager soundManager = mock(SoundManager.class);

		when(config.overlayScalePercent()).thenReturn(100);
		when(config.panelStyle()).thenReturn(PanelStyle.COMPACT);
		when(config.previewTier()).thenReturn(PreviewTier.NONE);

		overlay = new CollectionLogOverlay(client, itemManager, config, soundManager);
	}

	private void stubViewport(int canvasWidth, int xOffset, int width)
	{
		when(client.getRealDimensions()).thenReturn(new Dimension(canvasWidth, 720));
		when(client.getViewportXOffset()).thenReturn(xOffset);
		when(client.getViewportWidth()).thenReturn(width);
	}

	/** The location is set before the no-item early return, so an idle frame is enough. */
	private Point renderAndReadLocation()
	{
		BufferedImage canvas = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
		return overlay.getPreferredLocation();
	}

	private void assertCenteredOn(int expectedCenterX)
	{
		assertEquals(expectedCenterX - PANEL_WIDTH / 2, renderAndReadLocation().x);
	}

	/** Sidebar closed: the viewport fills the canvas, so the two centers coincide. */
	@Test
	public void centersOnTheViewportInPlainResizable()
	{
		stubViewport(1280, 0, 1280);
		assertCenteredOn(640);
	}

	/** Fixed/classic offsets the viewport left of the sidebar inside a wider canvas. */
	@Test
	public void centersOnTheViewportInFixedMode()
	{
		stubViewport(1280, 108, 512);
		assertCenteredOn(364);
	}

	/** Fixed Resizable Hybrid narrows the viewport by 249px while isResized() still reads true. */
	@Test
	public void centersOnTheViewportUnderAHybridStyleNarrowedViewport()
	{
		stubViewport(1280, 0, 1280 - 249);
		assertCenteredOn((1280 - 249) / 2);
	}

	/** A 0-width viewport falls back to the canvas center rather than pinning the panel left. */
	@Test
	public void fallsBackToTheCanvasCenterWhenTheViewportIsDegenerate()
	{
		stubViewport(1280, 0, 0);
		assertCenteredOn(640);
	}

	/** y is TOP_MARGIN regardless of which branch ran. */
	@Test
	public void alwaysSitsAtTheTopMargin()
	{
		stubViewport(1280, 0, 1280);
		assertEquals(2, renderAndReadLocation().y);
	}

	/** A dragged location stands, even after the viewport it was centered on changes. */
	@Test
	public void keepsALocationTheUserDraggedIn()
	{
		stubViewport(1280, 0, 1280);
		renderAndReadLocation();
		overlay.setPreferredLocation(new Point(50, 300));
		assertEquals(new Point(50, 300), renderAndReadLocation());

		stubViewport(1600, 0, 1600);
		assertEquals(new Point(50, 300), renderAndReadLocation());
	}

	/** Snapped to another corner, RuneLite places it - no location may be forced on top. */
	@Test
	public void leavesASnappedCornerAlone()
	{
		stubViewport(1280, 0, 1280);
		renderAndReadLocation();
		overlay.setPreferredPosition(OverlayPosition.TOP_LEFT);
		overlay.setPreferredLocation(null);
		assertNull(renderAndReadLocation());
	}

	/** Reset (or snapping back onto TOP_CENTER) clears both, which hands the panel back to centering. */
	@Test
	public void resumesCenteringAfterAReset()
	{
		stubViewport(1280, 0, 1280);
		overlay.setPreferredLocation(new Point(50, 300));
		renderAndReadLocation();
		overlay.setPreferredPosition(null);
		overlay.setPreferredLocation(null);
		assertCenteredOn(640);
	}

	/** The previous frame's own point must not read as user-placed once the viewport moves. */
	@Test
	public void followsTheViewportAcrossFrames()
	{
		stubViewport(1280, 0, 1280);
		assertCenteredOn(640);
		stubViewport(1280, 108, 512);
		assertCenteredOn(364);
	}
}

package com.iviystical.collectionlogshowcase.overlay;

import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import com.iviystical.collectionlogshowcase.rarity.PreviewTier;
import com.iviystical.collectionlogshowcase.rarity.RarityTier;
import com.iviystical.collectionlogshowcase.sound.SoundManager;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.InOrder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Covers the "delay CoX popups until chest" queue behaviour. Each item is given a distinct tier so
 * the sound call - which fires once as an item is dequeued - identifies which one is showing;
 * nothing else about the current item is observable from outside.
 */
public class CollectionLogOverlayHoldTest
{
	// FOLD_MILLIS + ICON_POP_MILLIS + FADE_MILLIS, plus a margin. overlayDisplaySeconds is stubbed
	// to 0 below, so this is the whole lifetime of an item on screen.
	private static final long TOTAL_ANIMATION_MILLIS = 550 + 400 + 400 + 150;

	private CollectionLogShowcaseConfig config;
	private SoundManager soundManager;
	private CollectionLogOverlay overlay;

	@Before
	public void before()
	{
		Client client = mock(Client.class);
		ItemManager itemManager = mock(ItemManager.class);
		config = mock(CollectionLogShowcaseConfig.class);
		soundManager = mock(SoundManager.class);

		// Unstubbed these return 0, sending render() down its degenerate-viewport fallback.
		when(client.getViewportXOffset()).thenReturn(4);
		when(client.getViewportWidth()).thenReturn(1272);
		when(client.getRealDimensions()).thenReturn(new Dimension(1280, 720));

		when(config.overlayScalePercent()).thenReturn(100);
		when(config.overlayDisplaySeconds()).thenReturn(0);
		when(config.panelStyle()).thenReturn(PanelStyle.COMPACT);
		when(config.previewTier()).thenReturn(PreviewTier.NONE);
		when(config.showKillCount()).thenReturn(true);
		when(config.rightPanelStat()).thenReturn(RightPanelStat.DROP_RATE);
		when(config.showProgressBar()).thenReturn(true);
		when(config.bulkUnlockSfx()).thenReturn(false);
		when(config.colourCaption()).thenReturn(Color.WHITE);
		when(config.compactTextColour()).thenReturn(Color.WHITE);

		overlay = new CollectionLogOverlay(client, itemManager, config, soundManager);
	}

	private void enqueue(String name, RarityTier tier, boolean held)
	{
		overlay.enqueue(name, 1, tier, 0, false, null, null, null, null, null, null, List.of(), held);
	}

	/** One frame is enough to dequeue the next item - the clock only matters for expiry. */
	private void renderFrame()
	{
		BufferedImage canvas = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void heldItemDoesNotShowUntilReleased()
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);

		renderFrame();
		verify(soundManager, never()).play(RarityTier.VERY_RARE);
		assertFalse("a held item still counts as queued", overlay.isIdle());

		overlay.releaseHeld();
		renderFrame();
		verify(soundManager).play(RarityTier.VERY_RARE);
	}

	@Test
	public void audioOnlyPlaysSoundWithoutDrawing()
	{
		when(config.panelStyle()).thenReturn(PanelStyle.AUDIO_ONLY);
		enqueue("Twisted bow", RarityTier.VERY_RARE, false);

		BufferedImage canvas = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			assertNull(overlay.render(graphics));
		}
		finally
		{
			graphics.dispose();
		}
		verify(soundManager).play(RarityTier.VERY_RARE);
	}

	/**
	 * The queue is FIFO, so a held item sitting at the head must not stall the ones behind it - the
	 * player would otherwise lose every unrelated unlock until they opened the chest.
	 */
	@Test
	public void heldItemDoesNotBlockLaterUnlocks()
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);
		enqueue("Clue scroll reward", RarityTier.COMMON, false);

		renderFrame();

		verify(soundManager).play(RarityTier.COMMON);
		verify(soundManager, never()).play(RarityTier.VERY_RARE);
	}

	/**
	 * Drains the queue by rendering past each item's expiry. overlayDisplaySeconds is stubbed to 0
	 * here so the wait is the fold/pop/fade animation only, rather than five real seconds per item.
	 */
	@Test
	public void releasedItemsShowInUnlockOrder() throws InterruptedException
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);
		enqueue("Kodai insignia", RarityTier.RARE, true);

		overlay.releaseHeld();

		// Three passes: dequeue the first, dequeue the second once it expires, then let the second
		// expire too so the overlay ends up genuinely idle.
		for (int i = 0; i < 3; i++)
		{
			renderFrame();
			Thread.sleep(TOTAL_ANIMATION_MILLIS);
		}
		renderFrame();

		InOrder order = inOrder(soundManager);
		order.verify(soundManager).play(RarityTier.VERY_RARE);
		order.verify(soundManager).play(RarityTier.RARE);
		assertTrue(overlay.isIdle());
	}

	/** Exactly one sound per burst when bulkUnlockSfx is on, held items included. */
	@Test
	public void releasedBurstPlaysOneSound()
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);
		enqueue("Kodai insignia", RarityTier.RARE, true);

		overlay.releaseHeld();
		renderFrame();

		verify(soundManager, times(1)).play(RarityTier.VERY_RARE);
		verify(soundManager, never()).play(RarityTier.RARE);
	}
}

