package com.iviystical.collectionlogshowcase.overlay;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * The corner's single-line values are drawn without truncation, so an over-wide drop rate range
 * clips silently under the icon. Measured against the real font, the way KillCountLabelWidthTest
 * does for labels.
 */
public class DropRateWidthTest
{
	// CollectionLogOverlay#cornerTextMaxWidth at 100% scale: iconX - cornerPaddingX, where
	// iconX = (BASE_PANEL_WIDTH - BASE_ICON_CANVAS_SIZE) / 2 = (379 - 89) / 2.
	private static final int CORNER_TEXT_MAX_WIDTH = (379 - 89) / 2 - 16;

	// BASE_CORNER_VALUE_FONT_SIZE - the size a single-line value is drawn at.
	private static final float VALUE_FONT_SIZE = 19f;

	private static final FontMetrics METRICS;

	static
	{
		Font font = FontManager.getRunescapeBoldFont().deriveFont(VALUE_FONT_SIZE);
		Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		METRICS = graphics.getFontMetrics(font);
	}

	// The widest range the shipped dataset produces (Heron, across 6 sources). It does not fit, which
	// is the whole reason the compact form exists - if this ever starts fitting, the compact path is
	// dead code rather than broken.
	@Test
	public void theWidestRealRangeDoesNotFitExact()
	{
		assertTrue("\"1/5000 - 1/1845k\" now fits - re-check whether the compact form is still needed",
			METRICS.stringWidth("1/5000 - 1/1845k") > CORNER_TEXT_MAX_WIDTH);
	}

	// Its compact rendering must fit, or the fallback buys nothing.
	@Test
	public void theCompactFormOfTheWidestRealRangeFits()
	{
		assertFits("1/5k - 1/1845k");
	}

	// The compact form only helps where a 4-digit denominator becomes one decimal of k; these are
	// the widest such ranges in the dataset.
	@Test
	public void compactFormsOfTheOtherWideRangesFit()
	{
		assertFits("1/5.8k - 1/313k");
		assertFits("1/1.5k - 1/3k");
		assertFits("1/1.2k - 1/3k");
		assertFits("1/4.5k - 1/5.4k");
	}

	// Ranges that already fit are shown exactly, so they have to keep fitting.
	@Test
	public void typicalExactRangesStillFit()
	{
		assertFits("1/1232 - 1/3003");
		assertFits("1/1500 - 1/3000");
		assertFits("1/540 - 1/1350");
		assertFits("1/160k - 1/800k");
	}

	private static void assertFits(String text)
	{
		int width = METRICS.stringWidth(text);
		assertTrue("\"" + text + "\" measures " + width + "px, over the " + CORNER_TEXT_MAX_WIDTH
			+ "px the panel gives a corner value - it would be drawn clipped", width <= CORNER_TEXT_MAX_WIDTH);
	}
}

package com.iviystical.collectionlogshowcase.overlay;

import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import com.iviystical.collectionlogshowcase.rarity.PreviewTier;
import com.iviystical.collectionlogshowcase.rarity.RarityTier;
import com.iviystical.collectionlogshowcase.sound.SoundManager;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class PreviewFadeTest
{
    @Test
    public void previewCollapsesAndExpiresUsingConfiguredDuration()
    {
        for (PreviewTier preview : new PreviewTier[] {PreviewTier.NONE, PreviewTier.COMMON})
        {
            Client client = mock(Client.class);
            when(client.getViewportWidth()).thenReturn(800);
            CollectionLogShowcaseConfig config = new CollectionLogShowcaseConfig()
            {
                @Override public PreviewTier previewTier() { return preview; }
                @Override public int overlayDisplaySeconds() { return 0; }
                @Override public int fadeOutMillis() { return 600; }
                @Override public boolean compactShimmer() { return false; }
            };
            AtomicLong clock = new AtomicLong();
            CollectionLogOverlay overlay = new CollectionLogOverlay(client, mock(ItemManager.class), config, mock(SoundManager.class), clock::get);
            overlay.enqueue("Mask of Ranul", -1, RarityTier.UNCOMMON, 8511, false, null, null, null, null, .001, List.of());
            render(overlay);
            clock.set(950);
            assertEquals(255, render(overlay).getRGB(10, 10) >>> 24);
            clock.set(1250);
            BufferedImage closing = render(overlay);
            assertEquals("item compartment stays opaque", 255, closing.getRGB(10, 10) >>> 24);
            assertEquals("drawer right edge retracts", 0, closing.getRGB(319, 10) >>> 24);
            assertFalse(overlay.isIdle());
            clock.set(1550);
            assertEquals(0, render(overlay).getRGB(10, 10) >>> 24);
            assertTrue(overlay.isIdle());
        }
    }

    @Test
    public void screenshotWaitsForRevealAndDoesNotRepeat()
    {
        Client client = mock(Client.class);
        when(client.getViewportWidth()).thenReturn(800);
        CollectionLogShowcaseConfig config = new CollectionLogShowcaseConfig() {};
        AtomicLong clock = new AtomicLong();
        CollectionLogOverlay overlay = new CollectionLogOverlay(client, mock(ItemManager.class), config, mock(SoundManager.class), clock::get);
        java.util.function.Consumer<String> captured = mock(java.util.function.Consumer.class);
        overlay.setReleasedFullyOpenListener(captured);
        overlay.enqueue("Mask of Ranul", -1, RarityTier.UNCOMMON, 8511, false, null, null, null, null, null, .001, List.of(), false, true);
        render(overlay);
        clock.set(1499);
        render(overlay);
        verifyNoInteractions(captured);
        clock.set(1500);
        render(overlay);
        clock.set(1600);
        render(overlay);
        verify(captured, times(1)).accept("Mask of Ranul");
        assertFalse(config.previewLoop());
    }

    private BufferedImage render(CollectionLogOverlay overlay)
    {
        BufferedImage image = new BufferedImage(400, 120, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try { overlay.render(graphics); }
        finally { graphics.dispose(); }
        return image;
    }
}

package com.iviystical.collectionlogshowcase.rarity;

import com.google.gson.Gson;
import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import com.iviystical.collectionlogshowcase.droprate.DropRateResolver;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.TileItem;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Pet resolution uses the collection-log dataset bundled with the plugin.
 */
public class ItemIdResolverTest
{
	private static final String FIXTURE = "/data/collection-log.json";

	private Client client;
	private ItemManager itemManager;
	private ItemIdResolver resolver;

	private static Map<String, RarityResolver.CompletionEntry> loadFixture()
	{
		InputStream stream = ItemIdResolverTest.class.getResourceAsStream(FIXTURE);
		org.junit.Assert.assertNotNull("Bundled dataset " + FIXTURE + " must be present", stream);
		Gson gson = new Gson();
		try (Reader reader = new InputStreamReader(stream))
		{
			return gson.fromJson(reader, RarityResolver.DATASET_TYPE);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	private static ItemPrice itemPrice(int id, String name)
	{
		ItemPrice itemPrice = new ItemPrice();
		itemPrice.setId(id);
		itemPrice.setName(name);
		return itemPrice;
	}

	private static void nameItem(ItemManager itemManager, int id, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(itemManager.getItemComposition(id)).thenReturn(composition);
	}

	private static ItemContainer inventoryOf(Item... items)
	{
		ItemContainer inventory = mock(ItemContainer.class);
		when(inventory.getItems()).thenReturn(items);
		return inventory;
	}

	/**
	 * Captures the id/source delivered to a ResolveCallback so tests can assert on it after the fact.
	 * Resolution is asynchronous now (see ItemIdResolver.resolveIdByName), so tests can't just take a
	 * return value.
	 */
	private static class CapturingCallback implements ItemIdResolver.ResolveCallback
	{
		private boolean called;
		private int value;
		private ItemIdResolver.Source source;

		@Override
		public void accept(int value, ItemIdResolver.Source source)
		{
			this.called = true;
			this.value = value;
			this.source = source;
		}
	}

	@Before
	public void before()
	{
		client = mock(Client.class);
		itemManager = mock(ItemManager.class);
		CollectionLogShowcaseConfig config = new CollectionLogShowcaseConfig()
		{
		};
		DropRateResolver dropRateResolver = mock(DropRateResolver.class);
		RarityResolver rarityResolver = new RarityResolver(itemManager, config, dropRateResolver);
		rarityResolver.reload(loadFixture());
		resolver = new ItemIdResolver(client, itemManager, rarityResolver);

		ItemContainer emptyInventory = inventoryOf();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(emptyInventory);
		when(itemManager.search(org.mockito.ArgumentMatchers.anyString())).thenReturn(Collections.emptyList());
	}

	@Test
	public void resolvesPetByNameWithoutTouchingInventoryOrGround()
	{
		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Baby mole", callback);

		assertEquals(net.runelite.api.gameval.ItemID.MOLEPET, callback.value);
		assertEquals(ItemIdResolver.Source.PET, callback.source);
	}

	@Test
	public void findsMatchInInventorySynchronously()
	{
		ItemContainer inventory = inventoryOf(new Item(100, 1), new Item(-1, 0));
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		nameItem(itemManager, 100, "Foo");

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Foo", callback);

		assertEquals(100, callback.value);
		assertEquals(ItemIdResolver.Source.INVENTORY, callback.source);
	}

	@Test
	public void findsMatchAmongTrackedGroundItemsSynchronously()
	{
		TileItem tileItem = mock(TileItem.class);
		when(tileItem.getId()).thenReturn(200);
		nameItem(itemManager, 200, "Bar");

		resolver.onItemSpawned(new ItemSpawned(null, tileItem));

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Bar", callback);

		assertEquals(200, callback.value);
		assertEquals(ItemIdResolver.Source.GROUND, callback.source);
	}

	@Test
	public void despawnedGroundItemNoLongerMatches()
	{
		TileItem tileItem = mock(TileItem.class);
		when(tileItem.getId()).thenReturn(201);
		nameItem(itemManager, 201, "Baz");

		resolver.onItemSpawned(new ItemSpawned(null, tileItem));
		resolver.onItemDespawned(new ItemDespawned(null, tileItem));

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Baz", callback);
		assertFalse("should defer rather than resolve immediately", callback.called);

		resolver.onGameTick(new GameTick());
		assertEquals(-1, callback.value);
		assertEquals(ItemIdResolver.Source.UNRESOLVED, callback.source);
	}

	@Test
	public void fallsBackToGeSearchAtEndOfTickWhenNotInInventoryOrOnGround()
	{
		when(itemManager.search("Twisted bow")).thenReturn(List.of(itemPrice(20997, "Twisted bow")));

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Twisted bow", callback);
		assertFalse("should defer rather than resolve immediately", callback.called);

		resolver.onGameTick(new GameTick());
		assertEquals(20997, callback.value);
		assertEquals(ItemIdResolver.Source.GE_SEARCH, callback.source);
	}

	@Test
	public void fallsBackToDatasetForUntradeableNotInInventoryOrOnGround()
	{
		// Guild hunter top is untradeable, so itemManager.search finds nothing (the @Before stubs an
		// empty GE result for every name) - the dataset index is the only check left that can resolve
		// it, and without it the popup renders a blank icon for id -1.
		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Guild hunter top", callback);
		assertFalse("should defer rather than resolve immediately", callback.called);

		resolver.onGameTick(new GameTick());
		assertEquals(29265, callback.value);
		assertEquals(ItemIdResolver.Source.DATASET, callback.source);
	}

	@Test
	public void prefersGeSearchOverDatasetWhenItemIsTradeable()
	{
		// The dataset only knows a canonical id, so a live-game check must always win where one is
		// available - here the GE search, which resolves the exact tradeable item.
		when(itemManager.search("Twisted bow")).thenReturn(List.of(itemPrice(20997, "Twisted bow")));

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Twisted bow", callback);
		resolver.onGameTick(new GameTick());

		assertEquals(20997, callback.value);
		assertEquals(ItemIdResolver.Source.GE_SEARCH, callback.source);
	}

	@Test
	public void datasetFallbackPicksLowestIdForNamesSharedByVariants()
	{
		// Chompy bird hat covers 18 ids, all cosmetic variants of one item; the name alone can't say
		// which, so the lowest is used as a representative sprite.
		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Chompy bird hat", callback);
		resolver.onGameTick(new GameTick());

		assertEquals(2978, callback.value);
		assertEquals(ItemIdResolver.Source.DATASET, callback.source);
	}

	@Test
	public void returnsMinusOneWhenNothingMatchesByEndOfTick()
	{
		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Nothing matches this", callback);

		resolver.onGameTick(new GameTick());
		assertEquals(-1, callback.value);
		assertEquals(ItemIdResolver.Source.UNRESOLVED, callback.source);
	}

	/**
	 * Reproduces the real-world bug: the unlock chat message arrives BEFORE the
	 * ItemContainerChanged that adds the item, so a synchronous check always falls back to -1. The
	 * resolver must wait for the inventory update and diff against the pre-message snapshot.
	 */
	@Test
	public void resolvesUntradeableItemFromDeferredInventoryDiff()
	{
		nameItem(itemManager, 300, "Partial note");

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Partial note", callback);
		assertFalse("id shouldn't be known yet - inventory hasn't updated", callback.called);

		ItemContainer updatedInventory = inventoryOf(new Item(300, 1));
		resolver.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, updatedInventory));

		assertEquals(300, callback.value);
		assertEquals(ItemIdResolver.Source.INVENTORY_DIFF, callback.source);
	}

	@Test
	public void ignoresItemContainerChangedForOtherContainers()
	{
		// Deliberately a name absent from the dataset: the point of the test is the assertFalse below,
		// and a real collection log name would now resolve via the dataset fallback on the tick,
		// masking whether the bank update itself was correctly ignored.
		nameItem(itemManager, 300, "Not a real item");

		CapturingCallback callback = new CapturingCallback();
		resolver.resolveIdByName("Not a real item", callback);

		ItemContainer bank = inventoryOf(new Item(300, 1));
		resolver.onItemContainerChanged(new ItemContainerChanged(InventoryID.BANK, bank));
		assertFalse("bank updates shouldn't resolve an inventory-bound lookup", callback.called);

		resolver.onGameTick(new GameTick());
		assertEquals(-1, callback.value);
		assertEquals(ItemIdResolver.Source.UNRESOLVED, callback.source);
	}
}

package com.iviystical.collectionlogshowcase.rarity;

import com.google.gson.Gson;
import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import com.iviystical.collectionlogshowcase.droprate.DropRateResolver;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Expected percentiles/tiers below are derived by replaying the resolver's exact algorithm in a
 * throwaway script against the real dataset fixture below (1705 scored entries as of writing) -
 * see conversation history for the derivation. These aren't hand-picked to "look right"; they're
 * the actual output of the composite-score + percentile-rank math for these real dataset ids.
 *
 * Uses the same bundled dataset shipped with the plugin; runs locally and in CI.
 */
public class RarityResolverTest
{
	private static final String FIXTURE = "/data/collection-log.json";

	private ItemManager itemManager;
	private DropRateResolver dropRateResolver;
	private RarityResolver resolver;
	private TestConfig config;

	/**
	 * Defaults to the real config's values; individual tests override the basis and the gp cutoffs.
	 */
	private static final class TestConfig implements CollectionLogShowcaseConfig
	{
		private RarityBasis basis = CollectionLogShowcaseConfig.super.rarityBasis();
		private int uncommon = CollectionLogShowcaseConfig.super.valueUncommonThreshold();
		private int rare = CollectionLogShowcaseConfig.super.valueRareThreshold();
		private int veryRare = CollectionLogShowcaseConfig.super.valueVeryRareThreshold();

		@Override
		public RarityBasis rarityBasis()
		{
			return basis;
		}

		@Override
		public int valueUncommonThreshold()
		{
			return uncommon;
		}

		@Override
		public int valueRareThreshold()
		{
			return rare;
		}

		@Override
		public int valueVeryRareThreshold()
		{
			return veryRare;
		}
	}

	@Before
	public void before()
	{
		itemManager = mock(ItemManager.class);
		// Default: no high alch value either, so unstubbed items behave as price-0 like before the
		// high alch fallback was added. Individual tests override this per-id where needed.
		ItemComposition defaultComposition = mock(ItemComposition.class);
		when(itemManager.getItemComposition(anyInt())).thenReturn(defaultComposition);
		// Default: no drop-rate data for any item, so unstubbed items behave as before the drop-rate
		// fallback was added. Individual tests override this per-name where needed.
		dropRateResolver = mock(DropRateResolver.class);
		when(dropRateResolver.dropProbabilityByItemName(anyString())).thenReturn(null);
		config = new TestConfig();
		resolver = new RarityResolver(itemManager, config, dropRateResolver);
		resolver.reload(loadFixture());
	}

	private static Map<String, RarityResolver.CompletionEntry> loadFixture()
	{
		InputStream stream = RarityResolverTest.class.getResourceAsStream(FIXTURE);
		org.junit.Assert.assertNotNull("Bundled dataset " + FIXTURE + " must be present", stream);
		Gson gson = new Gson();
		try (Reader reader = new InputStreamReader(stream))
		{
			return gson.fromJson(reader, RarityResolver.DATASET_TYPE);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	@Test
	public void petNameWinsRegardlessOfIdOrPrice()
	{
		assertEquals(RarityTier.PET, resolver.resolve(11849, "Baby mole").getTier());
	}

	@Test
	public void petNameMatchIsCaseInsensitive()
	{
		assertEquals(RarityTier.PET, resolver.resolve(-1, "baby MOLE").getTier());
	}

	// The wiki disambiguates item 31285 as "Gull (pet)", but the log slot - and so the chat
	// message this is keyed on - reads plain "Gull". Without the alias it tiers as an unknown
	// item and renders a blank icon.
	@Test
	public void petSuffixedDatasetNameIsFoundByItsSlotName()
	{
		assertEquals(RarityTier.PET, resolver.resolve(-1, "Gull").getTier());
		assertEquals(Integer.valueOf(31285), resolver.datasetIdForName("Gull"));
		assertEquals(List.of("Shellbane Gryphon", "All Pets"), resolver.tabsForItemName("Gull"));
	}

	// The suffixed name still resolves - it's what ::clogtest and the dataset itself use.
	@Test
	public void petSuffixedDatasetNameStillResolvesUnderItsFullName()
	{
		assertEquals(RarityTier.PET, resolver.resolve(-1, "Gull (pet)").getTier());
		assertEquals(Integer.valueOf(31285), resolver.datasetIdForName("Gull (pet)"));
	}

	// The mirror of the Gull case: the dataset stores item 31115 plain as "Eye of Ayak", but the
	// log slot - and so the chat message - reads "Eye of Ayak (uncharged)". Without the alias both
	// the tab lookup and the drop rate miss, so the popup loses its kill count and its drop rate
	// at once. Found by reading a client log against a real unlock.
	@Test
	public void unchargedSlotNameIsFoundByItsDatasetName()
	{
		assertEquals(Integer.valueOf(31115), resolver.datasetIdForName("Eye of ayak (uncharged)"));
		assertEquals(List.of("Doom of Mokhaiotl"), resolver.tabsForItemName("Eye of ayak (uncharged)"));
	}

	// The plain name still resolves - it is what the dataset itself is keyed on.
	@Test
	public void unchargedAliasDoesNotBreakThePlainName()
	{
		assertEquals(Integer.valueOf(31115), resolver.datasetIdForName("Eye of ayak"));
		assertEquals(List.of("Doom of Mokhaiotl"), resolver.tabsForItemName("Eye of ayak"));
	}

	// An entry the dataset already stores *with* the suffix must keep resolving under it, rather
	// than the alias stripping it and missing - 11 entries are stored that way.
	@Test
	public void datasetNamesThatCarryTheUnchargedSuffixStillResolve()
	{
		assertEquals(Integer.valueOf(22486), resolver.datasetIdForName("Scythe of vitur (uncharged)"));
		assertEquals(List.of("Theatre of Blood"), resolver.tabsForItemName("Scythe of vitur (uncharged)"));
	}

	// Dataset id 20011: comp_percent 0, tied with 9 other items for the rarest slot in the whole
	// dataset -> percentile 100 under default (unstubbed = zero) prices.
	@Test
	public void tiedRarestCompPercentIsVeryRare()
	{
		assertEquals(RarityTier.VERY_RARE, resolver.resolve(20011, "Not a pet").getTier());
	}

	// Dataset id 22100: comp_percent 0.3 -> percentile ~97.8
	@Test
	public void veryLowCompPercentIsVeryRare()
	{
		assertEquals(RarityTier.VERY_RARE, resolver.resolve(22100, "Not a pet").getTier());
	}

	// Dataset id 4508: comp_percent 1.3 -> percentile ~90.0
	@Test
	public void lowCompPercentIsRare()
	{
		assertEquals(RarityTier.RARE, resolver.resolve(4508, "Not a pet").getTier());
	}

	// Dataset id 4068: comp_percent 4.3 -> percentile ~70.2
	@Test
	public void midCompPercentIsUncommon()
	{
		assertEquals(RarityTier.UNCOMMON, resolver.resolve(4068, "Not a pet").getTier());
	}

	// Dataset id 2615: comp_percent 10.9 -> percentile ~30.5
	@Test
	public void higherCompPercentIsCommon()
	{
		assertEquals(RarityTier.COMMON, resolver.resolve(2615, "Not a pet").getTier());
	}

	// Dataset id 11849: comp_percent 96.8, the unique highest (least rare) value in the dataset.
	@Test
	public void highestCompPercentInDatasetIsCommon()
	{
		assertEquals(RarityTier.COMMON, resolver.resolve(11849, "Not a pet").getTier());
	}

	// An item with a price but no wiki completion score is bucketed on the same absolute gp cutoffs
	// the VALUE basis uses, so an identical price can't tier one way here and another way there.
	// This used to rank the price against a synthetic distribution, which called 1000gp VERY_RARE
	// purely because it topped that distribution - now 1000gp is simply below every cutoff.
	@Test
	public void unknownItemWithPriceIsBucketedByThreshold()
	{
		when(itemManager.getItemPrice(anyInt())).thenAnswer(invocation ->
		{
			int id = invocation.getArgument(0);
			return (long) (id % 1000) + 1;
		});

		RarityResult result = resolver.resolve(999_999, "Brand new item");
		assertEquals(RarityTier.COMMON, result.getTier());
		assertEquals(1000, result.getPrice());
	}

	@Test
	public void unknownItemWithHighPriceIsBucketedByThreshold()
	{
		when(itemManager.getItemPrice(999_999)).thenReturn(2_000_000L);

		RarityResult result = resolver.resolve(999_999, "Brand new expensive item");
		assertEquals(RarityTier.RARE, result.getTier());
	}

	// itemId -1 with completely unstubbed (all-zero) prices means there's no usable price signal
	// anywhere in the dataset - this must not be reported as VERY_RARE (that was the actual bug:
	// a fully degenerate/all-tied value-score distribution used to rank as the 100th percentile).
	// The item name isn't in the drop-rate mock either, so there's genuinely nothing to rank against.
	@Test
	public void noUsablePriceSignalAnywhereDefaultsToCommonInsteadOfFalseVeryRare()
	{
		RarityResult result = resolver.resolve(-1, "Some untradeable unresolved item");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	// Reported live: a brand-new boss-exclusive drop (e.g. "Crimson kisten") has no wiki completion
	// score yet AND no GE/alch price (untradeable), so both existing fallback signals are empty -
	// it used to always resolve as COMMON regardless of how rare it actually is. Drop probability is
	// the last resort: a very low per-kill rate should still rank as rare.
	@Test
	public void fallsBackToDropRateWhenNoCompletionAndNoPriceAreAvailable()
	{
		when(dropRateResolver.dropProbabilityByItemName("Crimson kisten")).thenReturn(0.0019230769230769162);

		RarityResult result = resolver.resolve(-1, "Crimson kisten");
		assertEquals(0, result.getPrice());
		assertEquals(RarityTier.VERY_RARE, result.getTier());
	}

	// If the item genuinely isn't in the drop-rate dataset either (mock default: null for every
	// name), there's still truly nothing to rank against, so it must keep defaulting to COMMON
	// rather than erroring or fabricating a score.
	@Test
	public void unknownItemWithNoDropRateEitherStillDefaultsToCommon()
	{
		RarityResult result = resolver.resolve(-1, "Some item with genuinely no data anywhere");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	@Test
	public void resultExposesCompPercentAndPriceForDisplay()
	{
		when(itemManager.getItemPrice(4508)).thenReturn(509L);

		RarityResult result = resolver.resolve(4508, "Not a pet");
		assertEquals(Double.valueOf(1.3), result.getCompPercent());
		assertEquals(509, result.getPrice());
	}

	// Many collection log items have no GE price (untradeable, or tradeable but unlisted) but still
	// have a high alch value, which is a better rarity signal than reporting price 0.
	@Test
	public void fallsBackToHighAlchValueWhenNoGePrice()
	{
		when(itemManager.getItemPrice(4508)).thenReturn(0L);
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(1000);
		when(itemManager.getItemComposition(4508)).thenReturn(composition);

		RarityResult result = resolver.resolve(4508, "Not a pet");
		assertEquals(1000, result.getPrice());
		assertEquals(true, result.isHighAlch());
	}

	@Test
	public void doesNotFallBackToHighAlchWhenGePriceIsPositive()
	{
		when(itemManager.getItemPrice(4508)).thenReturn(509L);
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(1000);
		when(itemManager.getItemComposition(4508)).thenReturn(composition);

		RarityResult result = resolver.resolve(4508, "Not a pet");
		assertEquals(509, result.getPrice());
		assertEquals(false, result.isHighAlch());
	}

	@Test
	public void unresolvedItemIdDoesNotFallBackToHighAlch()
	{
		// itemId -1 must short-circuit to price 0 without ever calling getItemComposition(-1)
		RarityResult result = resolver.resolve(-1, "Some untradeable unresolved item");
		assertEquals(0, result.getPrice());
		assertEquals(false, result.isHighAlch());
	}

	// Reported bug: a negative (int-overflowed) price on one item made every item rate 100th percentile.
	@Test
	public void negativePriceOnOneDatasetItemDoesNotPoisonEveryoneElsesPercentile()
	{
		when(itemManager.getItemPrice(2583)).thenReturn(-2L);

		RarityResult result = resolver.resolve(11849, "Not a pet");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	// Same failure from the other side: Integer.MAX_VALUE + 1 wraps negative in int arithmetic.
	@Test
	public void maxIntPriceOnOneDatasetItemDoesNotPoisonEveryoneElsesPercentile()
	{
		when(itemManager.getItemPrice(2583)).thenReturn((long) Integer.MAX_VALUE);

		RarityResult result = resolver.resolve(11849, "Not a pet");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	// Reported live: the poisoning also hit items with no completion data.
	@Test
	public void unknownItemStillResolvesSanelyWhenSomeDatasetPriceOverflows()
	{
		when(itemManager.getItemPrice(2583)).thenReturn((long) Integer.MAX_VALUE);

		RarityResult result = resolver.resolve(-1, "Cupric sulfate (Members)");
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	// --- Value basis: absolute gp thresholds (defaults 100k / 1m / 10m) ---

	private RarityTier tierForPrice(int price)
	{
		config.basis = RarityBasis.VALUE;
		when(itemManager.getItemPrice(4508)).thenReturn((long) price);
		return resolver.resolve(4508, "Not a pet").getTier();
	}

	@Test
	public void valueBasisBucketsEachBand()
	{
		assertEquals(RarityTier.COMMON, tierForPrice(99_999));
		assertEquals(RarityTier.UNCOMMON, tierForPrice(500_000));
		assertEquals(RarityTier.RARE, tierForPrice(5_000_000));
		assertEquals(RarityTier.VERY_RARE, tierForPrice(50_000_000));
	}

	// A price exactly on a cutoff belongs to the higher tier ("worth at least X").
	@Test
	public void valueBasisTreatsExactThresholdAsTheHigherTier()
	{
		assertEquals(RarityTier.UNCOMMON, tierForPrice(100_000));
		assertEquals(RarityTier.RARE, tierForPrice(1_000_000));
		assertEquals(RarityTier.VERY_RARE, tierForPrice(10_000_000));
	}

	// A zero price is simply below the lowest cutoff - there's no drop-rate fallback on this path,
	// so even an item with a very rare drop rate stays COMMON when it's worth nothing.
	@Test
	public void valueBasisTreatsUnpricedItemAsCommonWithoutDropRateFallback()
	{
		when(dropRateResolver.dropProbabilityByItemName("Crimson kisten")).thenReturn(0.0019230769230769162);
		config.basis = RarityBasis.VALUE;

		RarityResult result = resolver.resolve(-1, "Crimson kisten");
		assertEquals(0, result.getPrice());
		assertEquals(RarityTier.COMMON, result.getTier());
	}

	// The GE -> high alch fallback still feeds the threshold comparison.
	@Test
	public void valueBasisBucketsOnHighAlchWhenNoGePrice()
	{
		config.basis = RarityBasis.VALUE;
		when(itemManager.getItemPrice(4508)).thenReturn(0L);
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(2_000_000);
		when(itemManager.getItemComposition(4508)).thenReturn(composition);

		RarityResult result = resolver.resolve(4508, "Not a pet");
		assertEquals(RarityTier.RARE, result.getTier());
		assertEquals(true, result.isHighAlch());
	}

	@Test
	public void petStillWinsAheadOfThresholdsOnValueBasis()
	{
		config.basis = RarityBasis.VALUE;
		when(itemManager.getItemPrice(anyInt())).thenReturn(0L);

		assertEquals(RarityTier.PET, resolver.resolve(11849, "Baby mole").getTier());
	}

	// A user who types Rare below Uncommon still gets monotonic tiers rather than an unreachable band.
	@Test
	public void outOfOrderThresholdsAreSortedIntoMonotonicBands()
	{
		config.uncommon = 5_000_000;
		config.rare = 1_000_000;
		config.veryRare = 10_000_000;

		assertEquals(RarityTier.COMMON, tierForPrice(999_999));
		assertEquals(RarityTier.UNCOMMON, tierForPrice(1_000_000));
		assertEquals(RarityTier.RARE, tierForPrice(5_000_000));
		assertEquals(RarityTier.VERY_RARE, tierForPrice(10_000_000));
	}

	@Test
	public void negativeThresholdsAreClampedToZero()
	{
		config.uncommon = -1;
		config.rare = 1_000_000;
		config.veryRare = 10_000_000;

		// Clamped to 0, so even a free item clears the lowest cutoff.
		assertEquals(RarityTier.UNCOMMON, tierForPrice(0));
	}

	// --- Combination basis: still percentile-ranked, but the value half honours the thresholds ---

	// The regression guard that proves the gp fields actually reach the DEFAULT basis: raising a
	// threshold past the item's price drops its value score, so its composite score falls too.
	@Test
	public void raisingThresholdPastPriceLowersCombinationValueScore()
	{
		when(itemManager.getItemPrice(4508)).thenReturn(2_000_000L);

		double before = resolver.resolve(4508, "Not a pet").getValueScore();
		config.rare = 50_000_000;
		config.veryRare = 100_000_000;
		double after = resolver.resolve(4508, "Not a pet").getValueScore();

		assertEquals(2 / 3.0, before, 1e-9);
		assertEquals(1 / 3.0, after, 1e-9);
	}

	// The inconsistency this change closes: an item with a price but no comp% must tier the same way
	// whether the basis is VALUE or COMBINATION, since both are value-driven for such an item.
	@Test
	public void combinationAgreesWithValueForPricedItemWithNoCompPercent()
	{
		when(itemManager.getItemPrice(999_999)).thenReturn(2_000_000L);

		config.basis = RarityBasis.COMBINATION;
		RarityTier combination = resolver.resolve(999_999, "Brand new item").getTier();
		config.basis = RarityBasis.VALUE;
		RarityTier value = resolver.resolve(999_999, "Brand new item").getTier();

		assertEquals(value, combination);
		assertEquals(RarityTier.RARE, combination);
	}

	// The RARITY basis ranks comp% only and must stay completely unaffected by the gp thresholds.
	@Test
	public void rarityBasisIsUnaffectedByThresholds()
	{
		config.basis = RarityBasis.RARITY;
		when(itemManager.getItemPrice(4508)).thenReturn(50_000_000L);

		RarityTier expensive = resolver.resolve(4508, "Not a pet").getTier();
		config.uncommon = 1;
		config.rare = 2;
		config.veryRare = 3;
		RarityTier afterThresholdChange = resolver.resolve(4508, "Not a pet").getTier();

		assertEquals(RarityTier.RARE, expensive);
		assertEquals(expensive, afterThresholdChange);
	}
}

package com.iviystical.collectionlogshowcase.sound;

import com.iviystical.collectionlogshowcase.CollectionLogShowcaseConfig;
import com.iviystical.collectionlogshowcase.rarity.RarityTier;
import java.io.BufferedInputStream;
import java.io.InputStream;
import java.util.concurrent.ScheduledExecutorService;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import net.runelite.client.audio.AudioPlayer;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import net.runelite.client.util.Filepath;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

public class VoiceAudioTest
{
    @Test
    public void everyBundledVoiceIsDecodable() throws Exception
    {
        for (CollectionVoice voice : CollectionVoice.values())
        {
            if (voice.resource() == null) { continue; }
            try (InputStream input = getClass().getResourceAsStream(voice.resource()))
            {
                assertNotNull(voice.toString(), input);
                try (AudioInputStream audio = AudioSystem.getAudioInputStream(new BufferedInputStream(input)))
                {
                    assertTrue(audio.getFrameLength() > 0);
                    assertTrue(audio.getFormat().getSampleRate() > 0);
                }
            }
        }
    }

    @Test
    public void allTiersUseOneVoiceAndMutePreventsScheduling() throws Exception
    {
        CollectionLogShowcaseConfig config = mock(CollectionLogShowcaseConfig.class);
        AudioPlayer player = mock(AudioPlayer.class);
        ScheduledExecutorService executor = mock(ScheduledExecutorService.class);
        when(config.soundEnabled()).thenReturn(true);
        when(config.soundVolume()).thenReturn(65);
        when(config.collectionVoice()).thenReturn(CollectionVoice.C_ENGINEER);
        doAnswer(invocation -> { ((Runnable) invocation.getArgument(0)).run(); return null; }).when(executor).execute(any(Runnable.class));
        SoundManager manager = new SoundManager(player, config, executor, () -> { throw new AssertionError("Bundled audio must not access the filesystem"); });
        for (RarityTier tier : RarityTier.values()) { manager.play(tier); }
        verify(player, times(RarityTier.values().length)).play(eq(SoundManager.class), eq(CollectionVoice.C_ENGINEER.resource()), anyFloat());
        clearInvocations(player, executor);
        when(config.soundEnabled()).thenReturn(false);
        manager.play(RarityTier.PET);
        verifyNoInteractions(player, executor);
        when(config.soundEnabled()).thenReturn(true);
        when(config.soundVolume()).thenReturn(0);
        manager.play(RarityTier.COMMON);
        verifyNoInteractions(player, executor);
    }
    @Test
    public void customAudioUsesFilepathOnlyOnTheExecutor() throws Exception
    {
        CollectionLogShowcaseConfig config = customConfig("custom.wav");
        AudioPlayer player = mock(AudioPlayer.class);
        ScheduledExecutorService executor = mock(ScheduledExecutorService.class);
        SoundManager.DirectoryProvider directoryProvider = mock(SoundManager.DirectoryProvider.class);
        Filepath directory = mock(Filepath.class);
        Filepath sound = mock(Filepath.class);
        when(directoryProvider.get()).thenReturn(directory);
        when(directory.joinSegment("custom.wav")).thenReturn(sound);
        when(sound.isFile()).thenReturn(true);
        SoundManager manager = new SoundManager(player, config, executor, directoryProvider);
        manager.play(RarityTier.RARE);
        verifyNoInteractions(directoryProvider, directory, sound, player);
        ArgumentCaptor<Runnable> task = ArgumentCaptor.forClass(Runnable.class);
        verify(executor).execute(task.capture());
        task.getValue().run();
        verify(directoryProvider).get();
        verify(directory).joinSegment("custom.wav");
        verify(directory).createDirectories();
        verify(player).play(eq(sound), anyFloat());
    }

    @Test
